// v3nb01_http_server_core / ex1 - reference solution (author only).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

export function safeSetHeader(
  res: ServerResponse,
  name: string,
  value: number | string | readonly string[],
): boolean {
  // Once the header block is on the wire there is nothing to set: report it
  // rather than throwing ERR_HTTP_HEADERS_SENT from someone else's stack.
  if (res.headersSent) return false;
  res.setHeader(name, value as number | string | string[]);
  return true;
}

function sendJson(res: ServerResponse, status: number, value: unknown): void {
  const body = Buffer.from(JSON.stringify(value), "utf8");
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    // Buffer length is a byte count by construction; string .length is not.
    "content-length": body.length,
  });
  res.end(body);
}

function collectQuery(url: URL): Record<string, string | string[]> {
  const query: Record<string, string | string[]> = {};
  for (const key of new Set(url.searchParams.keys())) {
    const values = url.searchParams.getAll(key);
    query[key] = values.length === 1 ? values[0] : values;
  }
  return query;
}

export function createHandler(): Handler {
  let generated = 0;

  return (req, res) => {
    const incoming = req.headers["x-request-id"];
    const requestId =
      typeof incoming === "string" && incoming.length > 0
        ? incoming
        : `req-${(generated += 1)}`;
    safeSetHeader(res, "x-request-id", requestId);

    const url = new URL(req.url ?? "/", "http://localhost");
    if (req.method !== "GET" || url.pathname !== "/echo") {
      sendJson(res, 404, { error: "not_found" });
      return;
    }

    sendJson(res, 200, {
      method: req.method,
      pathname: url.pathname,
      query: collectQuery(url),
      // Distinct names: Node has already lowercased and folded duplicates.
      headerNames: Object.keys(req.headers).length,
    });
  };
}

// v3nb01_http_server_core / ex2 - reference solution (author only).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

function tooLarge(): Error & { status: number; code: string } {
  return Object.assign(new Error("payload too large"), {
    status: 413,
    code: "E_TOO_LARGE",
  });
}

export async function readBody(
  req: IncomingMessage,
  limit: number,
): Promise<Buffer> {
  const declared = Number(req.headers["content-length"]);
  // Cheap refusal: the client told us it is too big, so do not read a byte.
  if (Number.isFinite(declared) && declared > limit) throw tooLarge();

  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    // The real enforcement: chunked requests carry no content-length, and a
    // declared one is only a claim.
    if (size > limit) {
      req.destroy();
      throw tooLarge();
    }
    chunks.push(buf);
  }
  return Buffer.concat(chunks);
}

function mediaType(value: string | undefined): string {
  return (value ?? "").split(";")[0].trim().toLowerCase();
}

function sendJson(res: ServerResponse, status: number, value: unknown): void {
  const body = Buffer.from(JSON.stringify(value), "utf8");
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": body.length,
  });
  res.end(body);
}

export function createHandler(limit: number): Handler {
  let nextId = 0;

  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (req.method !== "POST" || url.pathname !== "/notes") {
      sendJson(res, 404, { error: "not_found" });
      return;
    }

    if (mediaType(req.headers["content-type"]) !== "application/json") {
      sendJson(res, 415, { error: "unsupported_media_type" });
      return;
    }

    void readBody(req, limit)
      .then((body) => {
        // JSON.parse("") throws, so empty and malformed share one branch.
        JSON.parse(body.toString("utf8")) as unknown;
        const id = `note-${(nextId += 1)}`;
        res.setHeader("location", `/notes/${id}`);
        sendJson(res, 201, { id, size: body.length });
      })
      .catch((error: unknown) => {
        if (res.headersSent) return;
        if ((error as { code?: string }).code === "E_TOO_LARGE") {
          res.setHeader("connection", "close");
          sendJson(res, 413, { error: "payload_too_large", limit });
          return;
        }
        sendJson(res, 400, { error: "invalid_json" });
      });
  };
}

// v3nb01_http_server_core / ex3 - reference solution (author only).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

const MODES = ["buffered", "stream", "empty"] as const;
type Mode = (typeof MODES)[number];

export function createHandler(rows: ReadonlyArray<unknown>): Handler {
  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (req.method !== "GET" || url.pathname !== "/rows") {
      const body = Buffer.from(JSON.stringify({ error: "not_found" }), "utf8");
      res.writeHead(404, {
        "content-type": "application/json; charset=utf-8",
        "content-length": body.length,
      });
      res.end(body);
      return;
    }

    const raw = url.searchParams.get("mode") ?? "buffered";
    if (!(MODES as readonly string[]).includes(raw)) {
      const body = Buffer.from(
        JSON.stringify({ error: "bad_mode", allowed: MODES }),
        "utf8",
      );
      res.writeHead(400, {
        "content-type": "application/json; charset=utf-8",
        "content-length": body.length,
      });
      res.end(body);
      return;
    }

    const mode = raw as Mode;

    if (mode === "empty") {
      // 204 is bodiless: no content-type, no content-length, nothing to frame.
      res.writeHead(204);
      res.end();
      return;
    }

    if (mode === "buffered") {
      const body = Buffer.from(JSON.stringify(rows), "utf8");
      res.writeHead(200, {
        "content-type": "application/json; charset=utf-8",
        "content-length": body.length,
      });
      res.end(body);
      return;
    }

    // No length is known up front, so say nothing and let Node frame it as
    // chunked. Setting a length here would be a guess, and a guess that is
    // wrong truncates the body.
    res.writeHead(200, { "content-type": "application/x-ndjson" });
    for (const row of rows) res.write(`${JSON.stringify(row)}\n`);
    res.end();
  };
}

// v3nb01_http_server_core / ex4 - reference solution (author only).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

export interface CollectedHeaders {
  names: string[];
  all: Record<string, string[]>;
}

export function collectHeaders(req: IncomingMessage): CollectedHeaders {
  const names: string[] = [];
  const all: Record<string, string[]> = {};
  // rawHeaders is [name, value, name, value, ...] with original casing and
  // original order, and nothing folded away.
  for (let i = 0; i + 1 < req.rawHeaders.length; i += 2) {
    const name = req.rawHeaders[i].toLowerCase();
    names.push(name);
    (all[name] ??= []).push(req.rawHeaders[i + 1]);
  }
  return { names, all };
}

export function createHandler(): Handler {
  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (req.method !== "GET" || url.pathname !== "/headers") {
      const missing = Buffer.from(JSON.stringify({ error: "not_found" }), "utf8");
      res.writeHead(404, {
        "content-type": "application/json; charset=utf-8",
        "content-length": missing.length,
      });
      res.end(missing);
      return;
    }

    const { names, all } = collectHeaders(req);

    // One field can arrive several times AND carry a list each time; both
    // levels have to be flattened or a hop count is wrong.
    const forwardedFor = (all["x-forwarded-for"] ?? []).flatMap((value) =>
      value
        .split(",")
        .map((part) => part.trim())
        .filter((part) => part.length > 0),
    );

    const duplicated = Object.entries(all)
      .filter(([, values]) => values.length > 1)
      .map(([name]) => name)
      .sort();

    const body = Buffer.from(
      JSON.stringify({ names, forwardedFor, duplicated }),
      "utf8",
    );

    // appendHeader accumulates; two setHeader calls would replace.
    res.appendHeader("set-cookie", "a=1; Path=/");
    res.appendHeader("set-cookie", "b=2; Path=/");
    res.writeHead(200, {
      "content-type": "application/json; charset=utf-8",
      "content-length": body.length,
    });
    res.end(body);
  };
}

exercises.hints:
## Hint 1

There are two events that mean "this request is over" and only one of them is
the happy path. `res.on("close")` fires for both; `res.writableEnded` is the
discriminator — true when you ended the response yourself, false when the
socket went away first. Everything in this exercise hangs off that one
comparison.

## Hint 2

The abort listener is the whole mechanism:

```ts
const controller = new AbortController();
res.on("close", () => {
  if (!res.writableEnded) {
    stats.aborted += 1;
    controller.abort();
  }
});
```

Then `work(controller.signal)` gets cancellation for free, and so does anything
it passes the signal to — `fetch`, a timer wrapped in `setTimeout` with a
signal, a database driver that supports one.

## Hint 3

The `catch` needs to ask who caused the rejection before it counts anything:

- `controller.signal.aborted` is true → your own cancellation, stay silent;
- otherwise → a genuine failure, `failed += 1`, and answer 500 *if*
  `!res.headersSent`.

Writing to a response whose socket has already gone does not throw in Node —
it quietly does nothing — so the `headersSent` check is about not producing a
second status line on a live response, not about crash safety.

