// v3nb01_http_server_core / ex5 - reference solution (author only).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

export interface SlowStats {
  started: number;
  completed: number;
  aborted: number;
  failed: number;
}

export function createSlowHandler(
  work: (signal: AbortSignal) => Promise<unknown>,
): { handler: Handler; stats: SlowStats } {
  const stats: SlowStats = { started: 0, completed: 0, aborted: 0, failed: 0 };

  const sendJson = (res: ServerResponse, status: number, value: unknown) => {
    const body = Buffer.from(JSON.stringify(value), "utf8");
    res.writeHead(status, {
      "content-type": "application/json; charset=utf-8",
      "content-length": body.length,
    });
    res.end(body);
  };

  const handler: Handler = (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (req.method !== "GET" || url.pathname !== "/slow") {
      sendJson(res, 404, { error: "not_found" });
      return;
    }

    stats.started += 1;
    const controller = new AbortController();

    // "close" covers both endings; writableEnded says which one happened.
    res.on("close", () => {
      if (!res.writableEnded) {
        stats.aborted += 1;
        controller.abort();
      }
    });

    void work(controller.signal)
      .then((result) => {
        if (controller.signal.aborted || res.writableEnded) return;
        stats.completed += 1;
        sendJson(res, 200, { result });
      })
      .catch(() => {
        // A rejection we caused by aborting is not a failure of the work.
        if (controller.signal.aborted) return;
        stats.failed += 1;
        if (res.headersSent || res.writableEnded) return;
        sendJson(res, 500, { error: "work_failed" });
      });
  };

  return { handler, stats };
}

// v3nb01_http_server_core / ex6 - reference solution (author only).
import { createHash } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

const ALLOW = "DELETE, GET, HEAD";

function etagOf(body: Buffer): string {
  return `"${createHash("sha1").update(body).digest("base64")}"`;
}

function matchesIfNoneMatch(header: string | undefined, etag: string): boolean {
  if (header === undefined) return false;
  return header.split(",").some((candidate) => {
    const value = candidate.trim();
    if (value === "*") return true;
    // Weak comparison: W/"x" and "x" are the same representation for a
    // conditional GET.
    return value.replace(/^W\//, "") === etag;
  });
}

function sendJson(res: ServerResponse, status: number, value: unknown): void {
  const body = Buffer.from(JSON.stringify(value), "utf8");
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": body.length,
  });
  res.end(body);
}

export function createHandler(doc: unknown): Handler {
  let current: unknown = doc;
  let deleted = false;

  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (url.pathname !== "/doc") {
      sendJson(res, 404, { error: "not_found" });
      return;
    }

    const method = req.method ?? "GET";

    if (method === "DELETE") {
      if (deleted) {
        sendJson(res, 404, { error: "not_found" });
        return;
      }
      deleted = true;
      current = undefined;
      // 204: no body, and therefore no content-length to describe one.
      res.writeHead(204);
      res.end();
      return;
    }

    if (method !== "GET" && method !== "HEAD") {
      const body = Buffer.from(
        JSON.stringify({ error: "method_not_allowed" }),
        "utf8",
      );
      res.writeHead(405, {
        allow: ALLOW,
        "content-type": "application/json; charset=utf-8",
        "content-length": body.length,
      });
      res.end(body);
      return;
    }

    if (deleted) {
      const body = Buffer.from(JSON.stringify({ error: "not_found" }), "utf8");
      res.writeHead(404, {
        "content-type": "application/json; charset=utf-8",
        "content-length": body.length,
      });
      res.end(method === "HEAD" ? undefined : body);
      return;
    }

    const body = Buffer.from(JSON.stringify(current), "utf8");
    const etag = etagOf(body);

    if (matchesIfNoneMatch(req.headers["if-none-match"], etag)) {
      // Validators and caching headers only: a 304 describes no body at all.
      res.writeHead(304, { etag, "cache-control": "no-cache" });
      res.end();
      return;
    }

    res.writeHead(200, {
      "content-type": "application/json; charset=utf-8",
      "content-length": body.length,
      "cache-control": "no-cache",
      etag,
    });
    // HEAD earns identical headers by running the identical path.
    res.end(method === "HEAD" ? undefined : body);
  };
}

exercises.hints:
## Hint 1

The reason this is `pipeline` and not a `for await` loop with `res.write` is
backpressure. `write()` returns `false` when the socket buffer is full; a loop
that ignores it buffers the rest of the export in your process, which is how a
streaming endpoint turns into an out-of-memory incident on a slow mobile
client. `pipeline` waits for `drain`, and it destroys the source if the
destination dies.

## Hint 2

An async generator is the cleanest source for `pipeline`, and it is where the
batching lives:

```ts
async function* lines(): AsyncGenerator<string> {
  let buffer = "";
  for await (const row of source()) {
    buffer += `${JSON.stringify(row)}\n`;
    if (Buffer.byteLength(buffer) >= 8192) {
      yield buffer;
      buffer = "";
    }
  }
  if (buffer.length > 0) yield buffer;
}
await pipeline(lines(), res);
```

`pipeline` accepts an async iterable as its first argument and will construct
the `Readable` for you.

## Hint 3

The three failure branches are told apart by *when* they happen, and
`res.headersSent` is the clock — which means you must not send the headers
until you know the source can produce something. Pull the first chunk by hand,
then hand the rest to `pipeline`:

```ts
const iterator = lines()[Symbol.asyncIterator]();
const first = await iterator.next();          // may throw: still a clean 500
res.writeHead(200, { "content-type": "application/x-ndjson" });
```

After that point the status is spent. In the `catch`: if the code is
`ERR_STREAM_PREMATURE_CLOSE` or the response is destroyed, this was an abort;
if `res.headersSent` is true, it is a truncation and the only honest move is
`res.destroy()`, so the client sees an incomplete transfer rather than a
valid-looking short file; otherwise it is a clean 500.

