// v3nb01_http_server_core / ex7 - reference solution (author only).
import type { IncomingMessage, ServerResponse } from "node:http";
import { pipeline } from "node:stream/promises";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

export interface ExportStats {
  aborted: number;
  truncated: number;
  failed: number;
}

const BATCH_BYTES = 8192;

export function createExportHandler(
  source: () => AsyncIterable<unknown>,
): { handler: Handler; stats: ExportStats } {
  const stats: ExportStats = { aborted: 0, truncated: 0, failed: 0 };

  const handler: Handler = (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (req.method !== "GET" || url.pathname !== "/export.ndjson") {
      const body = Buffer.from(JSON.stringify({ error: "not_found" }), "utf8");
      res.writeHead(404, {
        "content-type": "application/json; charset=utf-8",
        "content-length": body.length,
      });
      res.end(body);
      return;
    }

    async function* lines(): AsyncGenerator<string> {
      let buffer = "";
      for await (const row of source()) {
        buffer += `${JSON.stringify(row)}\n`;
        // One write per row would cost a chunk header per row.
        if (Buffer.byteLength(buffer) >= BATCH_BYTES) {
          yield buffer;
          buffer = "";
        }
      }
      if (buffer.length > 0) yield buffer;
    }

    void (async () => {
      try {
        // Pull the first batch BEFORE committing to a status: a source that
        // fails immediately still deserves an honest 500.
        const iterator = lines()[Symbol.asyncIterator]();
        const first = await iterator.next();

        // No content-length: the length is not knowable, so let Node frame it
        // as chunked.
        res.writeHead(200, { "content-type": "application/x-ndjson" });

        const rest = async function* (): AsyncGenerator<string> {
          if (!first.done) yield first.value;
          while (true) {
            const next = await iterator.next();
            if (next.done) return;
            yield next.value;
          }
        };
        await pipeline(rest(), res);
      } catch (error) {
        const code = (error as NodeJS.ErrnoException).code;
        if (code === "ERR_STREAM_PREMATURE_CLOSE" || res.destroyed) {
          stats.aborted += 1;
          return;
        }
        if (res.headersSent) {
          // The status is spent. Destroying the socket is the only way to tell
          // the client that the NDJSON it received is incomplete.
          stats.truncated += 1;
          res.destroy();
          return;
        }
        stats.failed += 1;
        const body = Buffer.from(
          JSON.stringify({ error: "export_failed" }),
          "utf8",
        );
        res.writeHead(500, {
          "content-type": "application/json; charset=utf-8",
          "content-length": body.length,
        });
        res.end(body);
      }
    })();
  };

  return { handler, stats };
}

// v3nb01_http_server_core / ex8 - reference solution (author only).
import type { Server } from "node:http";
import type { Socket } from "node:net";

export interface TimeoutOptions {
  proxyIdleMs: number;
  maxUploadMs: number;
}

export interface AppliedTimeouts {
  keepAliveTimeout: number;
  headersTimeout: number;
  requestTimeout: number;
  timeout: number;
}

function check(name: string, value: number): void {
  if (!Number.isInteger(value) || value <= 0) {
    throw new RangeError(`${name} must be a positive integer, got ${value}`);
  }
}

export function applyTimeouts(
  server: Server,
  opts: TimeoutOptions,
): AppliedTimeouts {
  check("proxyIdleMs", opts.proxyIdleMs);
  check("maxUploadMs", opts.maxUploadMs);

  // Outlive the proxy's idle timeout, or the proxy will hand a request to a
  // socket we have just decided to close - the classic unexplained 502.
  const keepAliveTimeout = opts.proxyIdleMs + 1000;
  // Must exceed keepAliveTimeout: it is measured per request on a connection
  // that may have been idle.
  const headersTimeout = keepAliveTimeout + 5000;
  // Covers the whole request including the body, so the biggest honest upload
  // sets the floor.
  const requestTimeout = Math.max(opts.maxUploadMs, headersTimeout + 1000);

  server.keepAliveTimeout = keepAliveTimeout;
  server.headersTimeout = headersTimeout;
  server.requestTimeout = requestTimeout;
  // Raw socket inactivity: leave it off and let the phase-specific clocks work.
  server.timeout = 0;

  return { keepAliveTimeout, headersTimeout, requestTimeout, timeout: 0 };
}

function rawResponse(status: number, reason: string): string {
  return (
    `HTTP/1.1 ${status} ${reason}\r\n` +
    "connection: close\r\n" +
    "content-length: 0\r\n" +
    "\r\n"
  );
}

export function attachClientErrorHandler(server: Server): void {
  server.on("clientError", (error: NodeJS.ErrnoException, socket: Socket) => {
    // No request object exists here: the parser rejected the bytes.
    if (socket.destroyed || !socket.writable) {
      socket.destroy();
      return;
    }
    if (error.code === "ECONNRESET") {
      // The peer is already gone; writing would raise a second error event.
      socket.destroy();
      return;
    }
    if (error.code === "HPE_HEADER_OVERFLOW") {
      socket.end(rawResponse(431, "Request Header Fields Too Large"));
      return;
    }
    socket.end(rawResponse(400, "Bad Request"));
  });
}

// v3nb01_http_server_core / challenge - reference solution (author only).
import { createHash } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

interface Item {
  id: string;
  title: string;
}

const BODY_LIMIT = 1024;
const IMPLEMENTED = new Set(["GET", "HEAD", "POST", "DELETE"]);

function etagOf(body: Buffer): string {
  return `"${createHash("sha1").update(body).digest("base64")}"`;
}

function ifNoneMatchHits(header: string | undefined, etag: string): boolean {
  if (header === undefined) return false;
  return header.split(",").some((raw) => {
    const value = raw.trim();
    return value === "*" || value.replace(/^W\//, "") === etag;
  });
}

async function readBody(req: IncomingMessage, limit: number): Promise<Buffer> {
  const declared = Number(req.headers["content-length"]);
  if (Number.isFinite(declared) && declared > limit) {
    throw Object.assign(new Error("too large"), { code: "E_TOO_LARGE" });
  }
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    if (size > limit) {
      req.destroy();
      throw Object.assign(new Error("too large"), { code: "E_TOO_LARGE" });
    }
    chunks.push(buf);
  }
  return Buffer.concat(chunks);
}

export function createApp(): Handler {
  const items = new Map<string, Item>();
  let nextItem = 0;
  let nextRequest = 0;

  const sendJson = (res: ServerResponse, status: number, value: unknown,
                    extra: Record<string, string> = {}, head = false) => {
    const body = Buffer.from(JSON.stringify(value), "utf8");
    res.writeHead(status, {
      ...extra,
      "content-type": "application/json; charset=utf-8",
      "content-length": body.length,
    });
    res.end(head ? undefined : body);
  };

  return (req, res) => {
    // Set before any branch, so every exit - 204, 304, 501 - carries it.
    res.setHeader("x-request-id", `r-${(nextRequest += 1)}`);

    const method = req.method ?? "GET";
    if (!IMPLEMENTED.has(method)) {
      sendJson(res, 501, { error: "not_implemented" });
      return;
    }

    const url = new URL(req.url ?? "/", "http://localhost");
    const segments = url.pathname.split("/").filter(Boolean);
    const head = method === "HEAD";

    // ---- collection -------------------------------------------------------
    if (segments.length === 1 && segments[0] === "items") {
      if (method === "GET" || head) {
        const body = Buffer.from(JSON.stringify([...items.values()]), "utf8");
        // The validator is a function of the bytes, so writes invalidate it
        // for free.
        const etag = etagOf(body);
        if (ifNoneMatchHits(req.headers["if-none-match"], etag)) {
          res.writeHead(304, { etag, "cache-control": "no-cache" });
          res.end();
          return;
        }
        res.writeHead(200, {
          "content-type": "application/json; charset=utf-8",
          "content-length": body.length,
          "cache-control": "no-cache",
          etag,
        });
        res.end(head ? undefined : body);
        return;
      }

      if (method === "POST") {
        const type = (req.headers["content-type"] ?? "")
          .split(";")[0]
          .trim()
          .toLowerCase();
        if (type !== "application/json") {
          sendJson(res, 415, { error: "unsupported_media_type" });
          return;
        }
        void readBody(req, BODY_LIMIT)
          .then((buffer) => {
            let parsed: unknown;
            try {
              parsed = JSON.parse(buffer.toString("utf8"));
            } catch {
              sendJson(res, 400, { error: "invalid_json" });
              return;
            }
            const title = (parsed as { title?: unknown } | null)?.title;
            if (typeof title !== "string" || title.trim().length === 0) {
              sendJson(res, 422, { error: "invalid_body", field: "title" });
              return;
            }
            const item: Item = { id: `item-${(nextItem += 1)}`, title };
            items.set(item.id, item);
            sendJson(res, 201, item, { location: `/items/${item.id}` });
          })
          .catch((error: unknown) => {
            if (res.headersSent) return;
            if ((error as { code?: string }).code === "E_TOO_LARGE") {
              sendJson(res, 413, {
                error: "payload_too_large",
                limit: BODY_LIMIT,
              }, { connection: "close" });
              return;
            }
            sendJson(res, 500, { error: "internal_error" });
          });
        return;
      }

      sendJson(res, 405, { error: "method_not_allowed" },
        { allow: "GET, HEAD, POST" });
      return;
    }

    // ---- item -------------------------------------------------------------
    if (segments.length === 2 && segments[0] === "items") {
      const id = decodeURIComponent(segments[1]);
      const item = items.get(id);

      if (method === "GET" || head) {
        if (item === undefined) {
          sendJson(res, 404, { error: "not_found" }, {}, head);
          return;
        }
        sendJson(res, 200, item, {}, head);
        return;
      }

      if (method === "DELETE") {
        if (item === undefined) {
          sendJson(res, 404, { error: "not_found" });
          return;
        }
        items.delete(id);
        // 204: nothing to frame, so nothing to declare.
        res.writeHead(204);
        res.end();
        return;
      }

      sendJson(res, 405, { error: "method_not_allowed" },
        { allow: "DELETE, GET, HEAD" });
      return;
    }

    sendJson(res, 404, { error: "not_found" }, {}, head);
  };
}

// v3nb01_http_server_core / review1 - reference solution (author only).
export type Target =
  | { form: "origin"; pathname: string; query: Record<string, string[]> }
  | { form: "absolute"; pathname: string; query: Record<string, string[]> }
  | { form: "authority"; authority: string }
  | { form: "asterisk" };

function bad(code: string, message: string): Error & { code: string; status: number } {
  return Object.assign(new Error(message), { code, status: 400 });
}

function collectQuery(url: URL): Record<string, string[]> {
  const query: Record<string, string[]> = {};
  // Iterating visits repeated keys once each, in arrival order.
  for (const [key, value] of url.searchParams) (query[key] ??= []).push(value);
  return query;
}

const AUTHORITY = /^[a-z0-9.-]+:\d{1,5}$/i;

export function parseRequestTarget(
  target: string,
  host: string | undefined,
): Target {
  if (typeof target !== "string" || target.length === 0) {
    throw bad("E_BAD_TARGET", "empty request target");
  }

  if (target === "*") return { form: "asterisk" };

  if (target.startsWith("/")) {
    if (host === undefined || host.trim().length === 0) {
      throw bad("E_NO_HOST", "origin-form target requires a Host header");
    }
    let url: URL;
    try {
      url = new URL(target, `http://${host}`);
    } catch {
      throw bad("E_BAD_TARGET", `unparseable origin-form target: ${target}`);
    }
    return { form: "origin", pathname: url.pathname, query: collectQuery(url) };
  }

  // Checked before new URL(), because "example.com:443" parses as a URL whose
  // scheme is "example.com:".
  if (AUTHORITY.test(target)) return { form: "authority", authority: target };

  let url: URL;
  try {
    url = new URL(target);
  } catch {
    throw bad("E_BAD_TARGET", `unrecognised request target: ${target}`);
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw bad("E_BAD_TARGET", `unsupported scheme: ${url.protocol}`);
  }
  if (host === undefined || host.trim().length === 0) {
    throw bad("E_NO_HOST", "absolute-form target requires a Host header");
  }
  // Disagreement between the request line and the Host header is the shape of
  // host-header injection: refuse it rather than picking a winner.
  if (url.host.toLowerCase() !== host.trim().toLowerCase()) {
    throw bad("E_HOST_MISMATCH", `${url.host} does not match Host: ${host}`);
  }
  return { form: "absolute", pathname: url.pathname, query: collectQuery(url) };
}

