// v3nb02_routing_pipeline / ex1 - reference solution (author only).
export type Middleware<C> = (ctx: C, next: () => Promise<void>) => unknown;

export function compose<C>(
  middlewares: ReadonlyArray<Middleware<C>>,
): (ctx: C, done?: () => unknown) => Promise<void> {
  return (ctx, done = () => undefined) => {
    // High-water mark: catches next() twice in a frame AND a stale next()
    // called after the stack has moved past it.
    let index = -1;

    const dispatch = (i: number): Promise<void> => {
      if (i <= index) {
        return Promise.reject(new Error("next() called multiple times"));
      }
      index = i;

      const fn = middlewares[i];
      if (fn === undefined) {
        // The tail is not a middleware: nothing runs after it.
        try {
          return Promise.resolve(done()).then(() => undefined);
        } catch (error) {
          return Promise.reject(error);
        }
      }

      try {
        // Promise.resolve lets a synchronous middleware compose; the catch
        // turns a synchronous throw into a rejection rather than an uncaught
        // exception.
        return Promise.resolve(fn(ctx, () => dispatch(i + 1))).then(
          () => undefined,
        );
      } catch (error) {
        return Promise.reject(error);
      }
    };

    return dispatch(0);
  };
}

// v3nb02_routing_pipeline / ex2 - reference solution (author only).
function split(value: string): string[] {
  return value.split("/").filter((part) => part.length > 0);
}

function decodeSegment(segment: string): string {
  try {
    // Per segment, never per path: %2F must stay data, not become structure.
    return decodeURIComponent(segment);
  } catch {
    throw Object.assign(new Error(`malformed path segment: ${segment}`), {
      code: "E_BAD_PARAM",
      status: 400,
    });
  }
}

export function matchPath(
  pattern: string,
  pathname: string,
): Record<string, string> | null {
  const pat = split(pattern);
  const wildcardAt = pat.indexOf("*");
  if (wildcardAt !== -1 && wildcardAt !== pat.length - 1) {
    // A developer mistake: fail loudly rather than silently never matching.
    throw new TypeError(`wildcard must be the final segment: ${pattern}`);
  }

  const path = split(pathname);
  const params: Record<string, string> = {};

  for (let i = 0; i < pat.length; i += 1) {
    const segment = pat[i];

    if (segment === "*") {
      params["*"] = path.slice(i).map(decodeSegment).join("/");
      return params;
    }

    if (i >= path.length) return null;

    if (segment.startsWith(":")) {
      params[segment.slice(1)] = decodeSegment(path[i]);
      continue;
    }

    if (segment !== path[i]) return null;
  }

  // Every pattern segment matched; the path must not have more.
  return pat.length === path.length ? params : null;
}

