// v3nb02_routing_pipeline / ex3 - reference solution (author only).
function split(value: string): string[] {
  return value.split("/").filter((part) => part.length > 0);
}

function decodeSegment(segment: string): string {
  try {
    return decodeURIComponent(segment);
  } catch {
    throw Object.assign(new Error(`malformed path segment: ${segment}`), {
      code: "E_BAD_PARAM",
      status: 400,
    });
  }
}

export function matchPath(
  pattern: string,
  pathname: string,
): Record<string, string> | null {
  const pat = split(pattern);
  const wildcardAt = pat.indexOf("*");
  if (wildcardAt !== -1 && wildcardAt !== pat.length - 1) {
    throw new TypeError(`wildcard must be the final segment: ${pattern}`);
  }
  const path = split(pathname);
  const params: Record<string, string> = {};
  for (let i = 0; i < pat.length; i += 1) {
    const segment = pat[i];
    if (segment === "*") {
      params["*"] = path.slice(i).map(decodeSegment).join("/");
      return params;
    }
    if (i >= path.length) return null;
    if (segment.startsWith(":")) {
      params[segment.slice(1)] = decodeSegment(path[i]);
      continue;
    }
    if (segment !== path[i]) return null;
  }
  return pat.length === path.length ? params : null;
}

export type RouteHandler = (params: Record<string, string>) => unknown;

export type Result =
  | {
      kind: "found";
      handler: RouteHandler;
      params: Record<string, string>;
      head: boolean;
    }
  | { kind: "method"; allow: string[] }
  | { kind: "missing" };

interface Route {
  method: string;
  pattern: string;
  handler: RouteHandler;
}

export function createRouter(): {
  add: (method: string, pattern: string, handler: RouteHandler) => void;
  find: (method: string, pathname: string) => Result;
} {
  const routes: Route[] = [];

  return {
    add(method, pattern, handler) {
      const upper = method.toUpperCase();
      if (routes.some((r) => r.method === upper && r.pattern === pattern)) {
        // Silent shadowing turns an import-order accident into a production
        // mystery; a boot-time throw turns it into a stack trace.
        throw new Error(`duplicate route: ${upper} ${pattern}`);
      }
      routes.push({ method: upper, pattern, handler });
    },

    find(method, pathname) {
      const wanted = method.toUpperCase();

      // Pass one: which patterns match the PATH, regardless of method.
      const matched: Array<Route & { params: Record<string, string> }> = [];
      for (const route of routes) {
        const params = matchPath(route.pattern, pathname);
        if (params !== null) matched.push({ ...route, params });
      }
      if (matched.length === 0) return { kind: "missing" };

      // Pass two: the method, exact first.
      const exact = matched.find((r) => r.method === wanted);
      if (exact) {
        return {
          kind: "found",
          handler: exact.handler,
          params: exact.params,
          head: false,
        };
      }

      if (wanted === "HEAD") {
        const get = matched.find((r) => r.method === "GET");
        if (get) {
          return {
            kind: "found",
            handler: get.handler,
            params: get.params,
            head: true,
          };
        }
      }

      const allow = new Set(matched.map((r) => r.method));
      if (allow.has("GET")) allow.add("HEAD");
      return { kind: "method", allow: [...allow].sort() };
    },
  };
}

// v3nb02_routing_pipeline / ex4 - reference solution (author only).
const RANK = { literal: 3, param: 2, wildcard: 1 } as const;

function split(value: string): string[] {
  return value.split("/").filter((part) => part.length > 0);
}

export function scoreOf(pattern: string): number[] {
  return split(pattern).map((segment) => {
    if (segment === "*") return RANK.wildcard;
    if (segment.startsWith(":")) return RANK.param;
    return RANK.literal;
  });
}

function matches(pattern: string, pathname: string): boolean {
  const pat = split(pattern);
  const path = split(pathname);
  for (let i = 0; i < pat.length; i += 1) {
    const segment = pat[i];
    if (segment === "*") return true;
    if (i >= path.length) return false;
    if (segment.startsWith(":")) continue;
    if (segment !== path[i]) return false;
  }
  return pat.length === path.length;
}

// Descending: the more specific pattern sorts first.
function compare(a: number[], b: number[]): number {
  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i += 1) {
    // Lexicographic, so the LEFTMOST difference decides. Summing the ranks
    // would lose position, which is the whole rule.
    if (a[i] !== b[i]) return b[i] - a[i];
  }
  return b.length - a.length;
}

export function mostSpecific(
  patterns: ReadonlyArray<string>,
  pathname: string,
): string | null {
  const candidates = patterns.filter((pattern) => matches(pattern, pathname));
  if (candidates.length === 0) return null;
  return [...candidates].sort((a, b) => compare(scoreOf(a), scoreOf(b)))[0];
}

// v3nb02_routing_pipeline / ex5 - reference solution (author only).
export type Middleware<C> = (ctx: C, next: () => Promise<void>) => unknown;

export interface Ctx {
  status: number;
  body: unknown;
  headersSent: boolean;
  aborted?: boolean;
}

function statusOf(error: unknown): number {
  const raw = (error as { status?: unknown } | null)?.status;
  if (
    typeof raw === "number" &&
    Number.isInteger(raw) &&
    raw >= 400 &&
    raw <= 599
  ) {
    return raw;
  }
  // Guilty until proven innocent: an error that did not declare itself
  // operational is treated as a bug.
  return 500;
}

function codeOf(error: unknown): string {
  const raw = (error as { code?: unknown } | null)?.code;
  return typeof raw === "string" && raw.length > 0 ? raw : "internal_error";
}

function messageOf(error: unknown): string {
  const raw = (error as { message?: unknown } | null)?.message;
  return typeof raw === "string" ? raw : String(error);
}

export function createErrorBoundary(
  report: (error: unknown) => void,
): Middleware<Ctx> {
  return async (ctx, next) => {
    try {
      await next();
    } catch (error) {
      const status = statusOf(error);
      if (status >= 500) report(error);

      if (ctx.headersSent) {
        // The status line is spent. Recording that we could not answer is the
        // only honest option.
        ctx.aborted = true;
        return;
      }

      ctx.status = status;
      ctx.body = {
        error: codeOf(error),
        // 5xx messages are written for your logs, not for a stranger's screen.
        message: status >= 500 ? "internal error" : messageOf(error),
      };
    }
  };
}

// v3nb02_routing_pipeline / ex6 - reference solution (author only).
export type Middleware<C> = (ctx: C, next: () => Promise<void>) => unknown;

export interface MountCtx {
  path: string;
  baseUrl: string;
}

export function mount<C extends MountCtx>(
  prefix: string,
  inner: Middleware<C>,
): Middleware<C> {
  const base = prefix.replace(/\/+$/, "");

  return async (ctx, next) => {
    // Segment boundary, not string prefix: /api must not swallow /apiv2.
    const under =
      base === "" || ctx.path === base || ctx.path.startsWith(`${base}/`);
    if (!under) {
      await next();
      return;
    }

    const savedPath = ctx.path;
    const savedBase = ctx.baseUrl;
    const rest = ctx.path.slice(base.length);

    ctx.baseUrl = savedBase + base;
    // An empty remainder is "/", or every downstream matcher sees nothing.
    ctx.path = rest.startsWith("/") ? rest : `/${rest}`;

    try {
      // The OUTER next: anything the sub-stack declines continues down the
      // parent stack, which is what makes a mount transparent.
      await inner(ctx, next);
    } finally {
      // On every path out, including a throw - or the error handler above
      // logs a URL the client never requested.
      ctx.path = savedPath;
      ctx.baseUrl = savedBase;
    }
  };
}

exercises.hints:
## Hint 1

Short-circuiting needs no mechanism at all — it is what happens by default when
a function returns without calling `next`. The work in this exercise is the
opposite: detecting the *misuse*, where a middleware answers the request and
then continues down the stack anyway, so the handler runs and tries to answer
again.

## Hint 2

The two lists concatenate into one composed stack with the handler as its tail:

```ts
const run = compose([...global, ...perRoute]);
return (ctx) => run(ctx, async () => {
  await handler(ctx);
  if (!ctx.sent) send(ctx, 204, null);
});
```

Per-route middleware is not a new concept; it is the same list with a different
scope, which is exactly how Express's `app.get(path, mw1, mw2, handler)` works
under the surface.

## Hint 3

The `next() after response` check belongs inside the `next` you hand out, not
inside the middlewares:

```ts
const nextFor = (i: number) => async () => {
  if (ctx.sent) throw new Error("next() after response");
  await dispatch(i + 1);
};
```

Enforcing an invariant in the one place that can see it, rather than trusting
every caller to check, is the same argument as the double-`next` guard in ex1 —
and it is why a framework can give you a useful error message where a
convention can only give you a comment.

