// v3nb02_routing_pipeline / ex7 - reference solution (author only).
export type Middleware<C> = (ctx: C, next: () => Promise<void>) => unknown;

export interface Ctx {
  sent: boolean;
  status: number;
  body: unknown;
  trace: string[];
}

export function send(ctx: Ctx, status: number, body: unknown): void {
  if (ctx.sent) {
    // The cheap, well-located version of ERR_HTTP_HEADERS_SENT.
    throw new Error(`response already sent (tried ${status})`);
  }
  ctx.sent = true;
  ctx.status = status;
  ctx.body = body;
}

export function chain(
  global: ReadonlyArray<Middleware<Ctx>>,
  perRoute: ReadonlyArray<Middleware<Ctx>>,
  handler: (ctx: Ctx) => unknown,
): (ctx: Ctx) => Promise<void> {
  // Per-route middleware is the same concept with a narrower scope.
  const stack = [...global, ...perRoute];

  return (ctx) => {
    let index = -1;

    const dispatch = (i: number): Promise<void> => {
      if (i <= index) {
        return Promise.reject(new Error("next() called multiple times"));
      }
      index = i;

      const fn = stack[i];
      if (fn === undefined) {
        return Promise.resolve(handler(ctx)).then(() => {
          // A handler that answered nothing still owes the client a response.
          if (!ctx.sent) send(ctx, 204, null);
        });
      }

      const next = async (): Promise<void> => {
        // The invariant lives where it can be seen, not in every caller.
        if (ctx.sent) throw new Error("next() after response");
        await dispatch(i + 1);
      };

      try {
        return Promise.resolve(fn(ctx, next)).then(() => undefined);
      } catch (error) {
        return Promise.reject(error);
      }
    };

    return dispatch(0);
  };
}

// v3nb02_routing_pipeline / ex8 - reference solution (author only).
import type { ServerResponse } from "node:http";

export type Middleware<C> = (ctx: C, next: () => Promise<void>) => unknown;

// Symbol.for, so two copies of this module loaded from different places still
// agree that a response has already been patched.
const PATCHED = Symbol.for("v3nb02.timing.patched");

export function createTimingMiddleware(
  now: () => number,
): Middleware<{ res: ServerResponse }> {
  return async (ctx, next) => {
    const res = ctx.res as ServerResponse & { [PATCHED]?: true };

    // Nothing to do: the header block is already on the wire.
    if (res.headersSent || res[PATCHED] === true) {
      await next();
      return;
    }

    res[PATCHED] = true;
    const started = now();
    const original = res.writeHead.bind(res);

    // The one moment where the duration is known AND headers are still
    // mutable. Node's implicit-header path calls writeHead too, so this also
    // covers a bare res.end(body).
    res.writeHead = ((...args: Parameters<ServerResponse["writeHead"]>) => {
      res.setHeader("server-timing", `app;dur=${(now() - started).toFixed(1)}`);
      return original(...args);
    }) as ServerResponse["writeHead"];

    await next();
  };
}

exercises.hints:
## Hint 1

Build it in the order the request meets it, and keep each piece in its own
function: parse the target, compose the stack, route, run the chain, write the
response. If any of those five needs to know about another, you have coupled
something that frameworks keep apart, and the symptom will be a test you cannot
write without starting a server.

## Hint 2

The router is a table plus a sort, done at registration:

```ts
const routes: Route[] = [];
const register = (method, pattern, chain) => {
  routes.push({ method, pattern, chain, score: scoreOf(pattern) });
  routes.sort((a, b) => compare(a.score, b.score));   // most specific first
};
```

Sorting on `add` rather than on every request is the whole performance argument
for precedence-based routing, and it makes `find` a plain `for` loop that
returns the first pattern match.

## Hint 3

The tail of the composed stack is where routing happens, which keeps `use`
middlewares oblivious to routes:

```ts
const run = compose(globals);
await run(ctx, async () => {
  const found = find(ctx.method, ctx.path);
  if (found.kind === "missing") return ctx.send(404, { error: "not_found" });
  if (found.kind === "method") {
    ctx.res.setHeader("allow", found.allow.join(", "));
    return ctx.send(405, { error: "method_not_allowed" });
  }
  ctx.params = found.params;
  await compose(found.chain)(ctx);
});
```

Note that the route chain is itself a composed stack — per-route middleware is
not a new mechanism, just a second call to the same function.

