// v3nb02_routing_pipeline / challenge - reference solution (author only).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Middleware<C> = (ctx: C, next: () => Promise<void>) => unknown;

export interface Ctx {
  req: IncomingMessage;
  res: ServerResponse;
  method: string;
  path: string;
  params: Record<string, string>;
  query: Record<string, string[]>;
  body: unknown;
  send: (status: number, value: unknown) => void;
}

const RANK = { literal: 3, param: 2, wildcard: 1 } as const;
const BODY_LIMIT = 65536;
const PATCHED = Symbol.for("v3nb02.timing.patched");

function split(value: string): string[] {
  return value.split("/").filter((part) => part.length > 0);
}

function decodeSegment(segment: string): string {
  try {
    return decodeURIComponent(segment);
  } catch {
    throw Object.assign(new Error("malformed path segment"), {
      code: "bad_param",
      status: 400,
    });
  }
}

function scoreOf(pattern: string): number[] {
  return split(pattern).map((s) =>
    s === "*" ? RANK.wildcard : s.startsWith(":") ? RANK.param : RANK.literal,
  );
}

function compare(a: number[], b: number[]): number {
  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i += 1) if (a[i] !== b[i]) return b[i] - a[i];
  return b.length - a.length;
}

function matchPath(
  pattern: string,
  pathname: string,
): Record<string, string> | null {
  const pat = split(pattern);
  const path = split(pathname);
  const params: Record<string, string> = {};
  for (let i = 0; i < pat.length; i += 1) {
    const segment = pat[i];
    if (segment === "*") {
      params["*"] = path.slice(i).map(decodeSegment).join("/");
      return params;
    }
    if (i >= path.length) return null;
    if (segment.startsWith(":")) {
      params[segment.slice(1)] = decodeSegment(path[i]);
      continue;
    }
    if (segment !== path[i]) return null;
  }
  return pat.length === path.length ? params : null;
}

function compose<C>(
  middlewares: ReadonlyArray<Middleware<C>>,
): (ctx: C, done?: () => unknown) => Promise<void> {
  return (ctx, done = () => undefined) => {
    let index = -1;
    const dispatch = (i: number): Promise<void> => {
      if (i <= index) {
        return Promise.reject(new Error("next() called multiple times"));
      }
      index = i;
      const fn = middlewares[i];
      try {
        if (fn === undefined) return Promise.resolve(done()).then(() => undefined);
        return Promise.resolve(fn(ctx, () => dispatch(i + 1))).then(
          () => undefined,
        );
      } catch (error) {
        return Promise.reject(error);
      }
    };
    return dispatch(0);
  };
}

async function readJsonBody(req: IncomingMessage): Promise<unknown> {
  const type = (req.headers["content-type"] ?? "").split(";")[0].trim();
  if (type.toLowerCase() !== "application/json") {
    throw Object.assign(new Error("expected application/json"), {
      code: "unsupported_media_type",
      status: 415,
    });
  }
  const declared = Number(req.headers["content-length"]);
  if (Number.isFinite(declared) && declared > BODY_LIMIT) {
    throw Object.assign(new Error("too large"), {
      code: "payload_too_large",
      status: 413,
    });
  }
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    if (size > BODY_LIMIT) {
      req.destroy();
      throw Object.assign(new Error("too large"), {
        code: "payload_too_large",
        status: 413,
      });
    }
    chunks.push(buf);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString("utf8")) as unknown;
  } catch {
    throw Object.assign(new Error("invalid JSON body"), {
      code: "invalid_json",
      status: 400,
    });
  }
}

interface Route {
  method: string;
  pattern: string;
  chain: Middleware<Ctx>[];
  score: number[];
}

export function createApp(options: { now: () => number }): {
  use: (mw: Middleware<Ctx>) => void;
  get: (pattern: string, ...chain: Middleware<Ctx>[]) => void;
  post: (pattern: string, ...chain: Middleware<Ctx>[]) => void;
  del: (pattern: string, ...chain: Middleware<Ctx>[]) => void;
  handler: (req: IncomingMessage, res: ServerResponse) => void;
} {
  const globals: Middleware<Ctx>[] = [];
  const routes: Route[] = [];

  const register = (
    method: string,
    pattern: string,
    chain: Middleware<Ctx>[],
  ) => {
    if (routes.some((r) => r.method === method && r.pattern === pattern)) {
      throw new Error(`duplicate route: ${method} ${pattern}`);
    }
    routes.push({ method, pattern, chain, score: scoreOf(pattern) });
    // Sorted once at registration, so lookup is a scan of an already-ordered
    // table rather than a sort per request.
    routes.sort((a, b) => compare(a.score, b.score));
  };

  const handler = (req: IncomingMessage, res: ServerResponse): void => {
    const url = new URL(req.url ?? "/", "http://localhost");
    const query: Record<string, string[]> = {};
    for (const [key, value] of url.searchParams) (query[key] ??= []).push(value);

    const method = (req.method ?? "GET").toUpperCase();
    const isHead = method === "HEAD";

    const ctx: Ctx = {
      req,
      res,
      method,
      path: url.pathname,
      params: {},
      query,
      body: undefined,
      send(status, value) {
        if (res.headersSent) return;
        if (status === 204) {
          res.writeHead(204);
          res.end();
          return;
        }
        const payload = Buffer.from(JSON.stringify(value ?? null), "utf8");
        res.writeHead(status, {
          "content-type": "application/json; charset=utf-8",
          "content-length": payload.length,
        });
        // HEAD earns the GET headers by running the GET path.
        res.end(isHead ? undefined : payload);
      },
    };

    // Timing first: it must wrap everything it claims to measure, and the
    // patch is the only way to reach the moment headers flush.
    const patched = res as ServerResponse & { [PATCHED]?: true };
    if (!res.headersSent && patched[PATCHED] !== true) {
      patched[PATCHED] = true;
      const started = options.now();
      const original = res.writeHead.bind(res);
      res.writeHead = ((...args: Parameters<ServerResponse["writeHead"]>) => {
        res.setHeader(
          "server-timing",
          `app;dur=${(options.now() - started).toFixed(1)}`,
        );
        return original(...args);
      }) as ServerResponse["writeHead"];
    }

    const route = async (): Promise<void> => {
      const matched: Array<{ route: Route; params: Record<string, string> }> =
        [];
      for (const candidate of routes) {
        const params = matchPath(candidate.pattern, ctx.path);
        if (params !== null) matched.push({ route: candidate, params });
      }
      if (matched.length === 0) {
        ctx.send(404, { error: "not_found" });
        return;
      }

      let hit = matched.find((m) => m.route.method === method);
      if (hit === undefined && isHead) {
        hit = matched.find((m) => m.route.method === "GET");
      }
      if (hit === undefined) {
        const allow = new Set(matched.map((m) => m.route.method));
        if (allow.has("GET")) allow.add("HEAD");
        res.setHeader("allow", [...allow].sort().join(", "));
        ctx.send(405, { error: "method_not_allowed" });
        return;
      }

      ctx.params = hit.params;
      if (method === "POST") ctx.body = await readJsonBody(req);
      await compose(hit.route.chain)(ctx);
    };

    void compose(globals)(ctx, route)
      .catch((error: unknown) => {
        const raw = (error as { status?: unknown } | null)?.status;
        const status =
          typeof raw === "number" && Number.isInteger(raw) && raw >= 400 && raw <= 599
            ? raw
            : 500;
        if (res.headersSent) {
          res.destroy();
          return;
        }
        const code = (error as { code?: unknown } | null)?.code;
        ctx.send(status, {
          error: typeof code === "string" ? code : "internal_error",
          message:
            status >= 500
              ? "internal error"
              : String((error as { message?: unknown } | null)?.message ?? ""),
        });
      })
      .then(() => {
        // A chain that answered nothing still owes the client a response.
        if (!res.headersSent) ctx.send(204, null);
      });
  };

  return {
    use: (mw) => void globals.push(mw),
    get: (pattern, ...chain) => register("GET", pattern, chain),
    post: (pattern, ...chain) => register("POST", pattern, chain),
    del: (pattern, ...chain) => register("DELETE", pattern, chain),
    handler,
  };
}

exercises.prompt:
## Review 1 — patterns, compiled once

Edit `review1/solution.ts`. Routers do not match patterns with string loops on
the hot path; they compile each pattern once at registration and then run a
regex. Export

```ts
interface Compiled { regex: RegExp; keys: string[]; score: number[] }
function compilePattern(pattern: string): Compiled;
function matchCompiled(compiled: Compiled, pathname: string):
  Record<string, string> | null;
```

Supported syntax:

- a literal segment matches itself, with regex metacharacters escaped — so
  `/files/report.pdf` must not match `/files/reportxpdf`;
- `:name` captures one segment, `[^/]+`;
- `:name?` is optional: `/users/:id?` matches both `/users` and `/users/7`,
  and the missing parameter is simply absent from the result;
- a trailing `*` captures the rest under `"*"`, and is absent from the result
  when there is nothing left (`/files/*` matches `/files` with no `"*"` key);
- a trailing slash is insignificant.

`score` follows ex4's ranks (`3` literal, `2` parameter — optional included —
`1` wildcard). `matchCompiled` percent-decodes each captured value and throws
the `E_BAD_PARAM` error from ex2 on malformed encoding.

```
uv run dojo test node v3nb02_routing_pipeline review1
```

