// v3nb02_routing_pipeline / review1 - reference solution (author only).
export interface Compiled {
  regex: RegExp;
  keys: string[];
  score: number[];
}

const RANK = { literal: 3, param: 2, wildcard: 1 } as const;

function split(value: string): string[] {
  return value.split("/").filter((part) => part.length > 0);
}

function escape(literal: string): string {
  // Without this, "report.pdf" would also match "reportxpdf".
  return literal.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function decodeSegment(segment: string): string {
  try {
    return decodeURIComponent(segment);
  } catch {
    throw Object.assign(new Error(`malformed path segment: ${segment}`), {
      code: "E_BAD_PARAM",
      status: 400,
    });
  }
}

export function compilePattern(pattern: string): Compiled {
  const segments = split(pattern);
  const keys: string[] = [];
  const score: number[] = [];
  let source = "";

  segments.forEach((segment, index) => {
    if (segment === "*") {
      if (index !== segments.length - 1) {
        throw new TypeError(`wildcard must be the final segment: ${pattern}`);
      }
      keys.push("*");
      score.push(RANK.wildcard);
      // Optional slash so /files/* also matches /files with an empty capture.
      source += "(?:/(.*))?";
      return;
    }

    if (segment.startsWith(":")) {
      const optional = segment.endsWith("?");
      keys.push(segment.slice(1, optional ? -1 : undefined));
      score.push(RANK.param);
      // The slash travels WITH the segment, so an optional one wraps cleanly.
      source += optional ? "(?:/([^/]+))?" : "/([^/]+)";
      return;
    }

    score.push(RANK.literal);
    source += `/${escape(segment)}`;
  });

  if (source === "") source = "/";
  return { regex: new RegExp(`^${source}\\/?$`), keys, score };
}

export function matchCompiled(
  compiled: Compiled,
  pathname: string,
): Record<string, string> | null {
  const found = compiled.regex.exec(pathname);
  if (found === null) return null;

  const params: Record<string, string> = {};
  compiled.keys.forEach((key, i) => {
    // Group 0 is the whole match; an optional group that did not participate
    // is undefined, and an absent parameter should be absent, not "".
    const raw = found[i + 1];
    if (raw !== undefined) params[key] = decodeSegment(raw);
  });
  return params;
}

lessons.fullReadme:
# V3·NB3 — Validation and error responses (archive)

## The boundary

```
  untyped ────────────────────────── typed
  req.body: unknown   ─▶ validate ─▶  CreateOrder
  req.query: strings  ─▶ coerce   ─▶  { page: number, tags: string[] }
  req.params: strings ─▶ check    ─▶  { id: OrderId }
```

Everything to the right of the arrows may be trusted by the rest of the
program. Everything to the left may not. A codebase that keeps this line sharp
can answer "where is input validated?" with a file name; one that does not
answers it with "everywhere, probably".

## A schema as data

```ts
export type Schema =
  | { kind: "string"; min?: number; max?: number; pattern?: RegExp }
  | { kind: "number"; int?: boolean; min?: number; max?: number }
  | { kind: "boolean" }
  | { kind: "array"; of: Schema; min?: number; max?: number }
  | { kind: "object"; fields: Record<string, Schema>; optional?: string[] };

export interface Issue { path: string; code: string; message: string }
```

The recursion writes itself, and the only real design work is the path:

```ts
function walk(schema: Schema, value: unknown, path: string, out: Issue[]): void {
  switch (schema.kind) {
    case "array": {
      if (!Array.isArray(value)) return push(out, path, "invalid_type", "expected an array");
      value.forEach((item, i) => walk(schema.of, item, `${path}[${i}]`, out));
      return;
    }
    case "object": {
      if (typeof value !== "object" || value === null || Array.isArray(value)) {
        return push(out, path, "invalid_type", "expected an object");
      }
      for (const [key, field] of Object.entries(schema.fields)) {
        const child = path === "" ? key : `${path}.${key}`;
        const present = Object.hasOwn(value, key);
        if (!present) {
          if (!schema.optional?.includes(key)) push(out, child, "required", "is required");
          continue;
        }
        walk(field, (value as Record<string, unknown>)[key], child, out);
      }
      return;
    }
    // ...scalars
  }
}
```

`Object.hasOwn` rather than `key in value` matters: `in` walks the prototype
chain, so `{}` "has" `constructor`, and a required-field check written with
`in` silently accepts a payload that supplies nothing.

## Coercion that does not guess

```ts
const asInt = (raw: string): number | null =>
  /^-?\d+$/.test(raw.trim()) ? Number(raw.trim()) : null;

const asBool = (raw: string): boolean | null => {
  const v = raw.trim().toLowerCase();
  if (v === "true" || v === "1") return true;
  if (v === "false" || v === "0") return false;
  return null;
};
```

Compare with the implicit versions, all of which are traps: `Number("")` is
`0`, `Number(" ")` is `0`, `Number("0x10")` is `16`, `parseInt("12abc")` is
`12`, and `Boolean("false")` is `true`. Each of those turns a bad request into
a plausible-looking wrong answer, which is worse than an error.

Common mistakes:

- **Accepting `NaN` through.** `Number(x)` succeeding is not the same as `x`
  being a number; test the string, not the result.
- **Treating a missing parameter as invalid.** Absent and present-but-wrong are
  different: one gets a default, the other gets an issue.
- **Last-wins on a repeated scalar.** `?page=1&page=99` is an ambiguous request;
  answering it silently picks a side.
- **Coercing before checking the media type.** A body you have not agreed to
  read should not be parsed at all.

## The problem document

```ts
export function problem(init: {
  type: string; title: string; status: number;
  detail?: string; instance?: string; errors?: Issue[];
}): { body: string; headers: Record<string, string> } {
  const body = JSON.stringify({ ...init });
  return {
    body,
    headers: {
      "content-type": "application/problem+json; charset=utf-8",
      "content-length": String(Buffer.byteLength(body)),
    },
  };
}
```

The `content-type` is the point. A client library can register one handler for
`application/problem+json` and get structured errors from every endpoint,
including ones written by other teams. Returning `application/json` with an
ad-hoc shape means every consumer writes a bespoke parser.

## Status selection, written down

| situation | status | client's next move |
| --- | --- | --- |
| body is not valid JSON | 400 | fix the serialisation |
| `content-type` not supported | 415 | send JSON |
| field missing or wrong type | 422 (or 400) | fix the values |
| cross-field rule broken | 422 | fix the values |
| duplicate key, stale ETag | 409 | read current state |
| not authenticated | 401 | get a token |
| authenticated, not permitted | 403 | stop |
| too many requests | 429 | wait `Retry-After` |

The rule that matters more than any individual row: be consistent across the
service, and put the reason in the body.

## Allowlisting, and the two vulnerabilities it closes

```ts
const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

export function sanitize(fields: Record<string, FieldRule>, input: Record<string, unknown>) {
  const value: Record<string, unknown> = {};
  for (const [key, rule] of Object.entries(fields)) {
    if (FORBIDDEN.has(key) || !Object.hasOwn(input, key)) continue;
    let current = input[key];
    if (typeof current === "string" && rule.trim) current = current.trim();
    value[key] = current;
  }
  return value;
}
```

**Mass assignment** is closed because the output is constructed from declared
fields; a client sending `"role": "admin"` contributes nothing. Rails shipped a
CVE for exactly this in 2012 — someone used it to commit to the Rails
repository — and every ORM since has an allowlisting mechanism, usually
optional and usually skipped under deadline.

**Prototype pollution** is closed because the three dangerous names are never
copied. `JSON.parse('{"__proto__": {"admin": true}}')` gives you an object with
an *own* `__proto__` key, and a recursive merge that assigns it can write onto
`Object.prototype`, at which point every object in the process reports
`admin === true`. The bug is rarely in your merge; it is in the deep-merge
utility three dependencies down.

## Caps, because the client picks the input

```ts
if (issues.length >= limits.maxIssues) return;
if (depth > limits.maxDepth) { push(path, "too_deep", "..."); return; }
const upTo = Math.min(value.length, limits.maxItems);
```

Three lines, three denial-of-service vectors. Depth is the sharpest: your
recursion uses the JavaScript stack, `JSON.parse` does not, so a ten-thousand
level payload parses fine and then overflows *your* walk with a `RangeError`
that no `catch` in the request path expects. The issue cap is the least
dramatic and the most frequently useful — it bounds your response size and your
log volume at the same time.

## The interview answers

*"Why validate when you have TypeScript?"* Types are erased at run time. `as`
is an assertion, not a check. The compiler protects you from your own code; a
validator protects you from everyone else's.

*"400 or 422?"* 400 for syntax, 422 for semantics, and the choice matters less
than consistency plus a body that says which field and why.

*"How do you avoid leaking internals in errors?"* Two channels: a `code` and a
path for the client, the stack and the input for the log. Never the message of
a 5xx.

## Check yourself

1. What does `as CreateOrder` check at run time?
2. Why collect issues instead of throwing at the first one?
3. Give three strings where implicit `Number()` produces a wrong-but-plausible
   value.
4. Why is `Object.hasOwn` safer than `in` for a required-field check?
5. What is the difference between 415 and 406?
6. What breaks if you return 200 with `{"success": false}`?
7. Which field of a problem document must never change once published?
8. How does stripping unknown keys prevent mass assignment?
9. Why skip `__proto__` when copying validated keys?
10. Why cap the number of reported issues?
11. When is 409 the right answer rather than 422?
12. Why should an error message never contain the offending value?
13. What is the advantage of `application/problem+json` over your own shape?

