// v3nb03_validation_errors / ex1 - reference solution (author only).
export type Schema =
  | { kind: "string"; min?: number; max?: number; pattern?: RegExp }
  | { kind: "number"; int?: boolean; min?: number; max?: number }
  | { kind: "boolean" }
  | { kind: "array"; of: Schema; min?: number; max?: number }
  | { kind: "object"; fields: Record<string, Schema>; optional?: string[] };

export interface Issue {
  path: string;
  code: string;
  message: string;
}

function push(out: Issue[], path: string, code: string, message: string): void {
  out.push({ path, code, message });
}

function walk(schema: Schema, value: unknown, path: string, out: Issue[]): void {
  switch (schema.kind) {
    case "string": {
      if (typeof value !== "string") {
        push(out, path, "invalid_type", "expected a string");
        return;
      }
      if (schema.min !== undefined && value.length < schema.min) {
        push(out, path, "too_small", `must be at least ${schema.min} characters`);
      }
      if (schema.max !== undefined && value.length > schema.max) {
        push(out, path, "too_large", `must be at most ${schema.max} characters`);
      }
      if (schema.pattern !== undefined && !schema.pattern.test(value)) {
        push(out, path, "invalid_format", "does not match the expected format");
      }
      return;
    }

    case "number": {
      // NaN and Infinity are typeof "number" and are never acceptable input.
      if (typeof value !== "number" || !Number.isFinite(value)) {
        push(out, path, "invalid_type", "expected a finite number");
        return;
      }
      if (schema.int === true && !Number.isInteger(value)) {
        push(out, path, "invalid_format", "must be a whole number");
      }
      if (schema.min !== undefined && value < schema.min) {
        push(out, path, "too_small", `must be at least ${schema.min}`);
      }
      if (schema.max !== undefined && value > schema.max) {
        push(out, path, "too_large", `must be at most ${schema.max}`);
      }
      return;
    }

    case "boolean": {
      if (typeof value !== "boolean") {
        push(out, path, "invalid_type", "expected a boolean");
      }
      return;
    }

    case "array": {
      if (!Array.isArray(value)) {
        // Return, or a string would be walked character by character.
        push(out, path, "invalid_type", "expected an array");
        return;
      }
      if (schema.min !== undefined && value.length < schema.min) {
        push(out, path, "too_small", `must have at least ${schema.min} items`);
      }
      if (schema.max !== undefined && value.length > schema.max) {
        push(out, path, "too_large", `must have at most ${schema.max} items`);
      }
      value.forEach((item, i) => walk(schema.of, item, `${path}[${i}]`, out));
      return;
    }

    case "object": {
      if (typeof value !== "object" || value === null || Array.isArray(value)) {
        push(out, path, "invalid_type", "expected an object");
        return;
      }
      const record = value as Record<string, unknown>;
      for (const [key, field] of Object.entries(schema.fields)) {
        const child = path === "" ? key : `${path}.${key}`;
        // hasOwn, not `in`: `in` walks the prototype chain and would accept a
        // field named "constructor" that nobody sent.
        const present =
          Object.hasOwn(record, key) && record[key] !== undefined;
        if (!present) {
          if (schema.optional?.includes(key) !== true) {
            push(out, child, "required", "is required");
          }
          continue;
        }
        walk(field, record[key], child, out);
      }
      return;
    }
  }
}

export function validate(
  schema: Schema,
  value: unknown,
): { ok: true; value: unknown } | { ok: false; issues: Issue[] } {
  const issues: Issue[] = [];
  walk(schema, value, "", issues);
  // Validation checks; it never rewrites. Transformation is a separate job.
  return issues.length === 0 ? { ok: true, value } : { ok: false, issues };
}

