// v3nb03_validation_errors / ex2 - reference solution (author only).
export interface Issue {
  path: string;
  code: string;
  message: string;
}

export type Field =
  | { kind: "int"; min?: number; max?: number; default?: number }
  | { kind: "bool"; default?: boolean }
  | { kind: "string"; default?: string }
  | { kind: "list"; of: "int" | "string"; max?: number };

const INTEGER = /^-?\d+$/;

function asInt(raw: string): number | null {
  // Test the STRING, then convert. Number("") is 0 and Number("0x10") is 16.
  const trimmed = raw.trim();
  return INTEGER.test(trimmed) ? Number(trimmed) : null;
}

function asBool(raw: string): boolean | null {
  const value = raw.trim().toLowerCase();
  if (value === "true" || value === "1") return true;
  if (value === "false" || value === "0") return false;
  return null;
}

export function coerceQuery(
  spec: Record<string, Field>,
  query: Record<string, string[]>,
):
  | { ok: true; value: Record<string, unknown> }
  | { ok: false; issues: Issue[] } {
  const issues: Issue[] = [];
  const out: Record<string, unknown> = {};

  for (const [name, field] of Object.entries(spec)) {
    // An empty value is an absent value: ?page= is not a page number.
    const values = (query[name] ?? []).filter((v) => v.trim() !== "");

    if (values.length === 0) {
      if (field.kind === "list") {
        out[name] = [];
        continue;
      }
      if (field.default !== undefined) {
        out[name] = field.default;
        continue;
      }
      issues.push({ path: name, code: "required", message: "is required" });
      continue;
    }

    if (field.kind !== "list" && values.length > 1) {
      // Never last-wins: an ambiguous request deserves an answer, not a guess.
      issues.push({
        path: name,
        code: "ambiguous",
        message: "expected a single value",
      });
      continue;
    }

    if (field.kind === "list") {
      if (field.max !== undefined && values.length > field.max) {
        issues.push({
          path: name,
          code: "too_large",
          message: `must have at most ${field.max} items`,
        });
        continue;
      }
      if (field.of === "string") {
        out[name] = values;
        continue;
      }
      const numbers: number[] = [];
      values.forEach((raw, i) => {
        const parsed = asInt(raw);
        if (parsed === null) {
          issues.push({
            path: `${name}[${i}]`,
            code: "invalid_format",
            message: "expected an integer",
          });
          return;
        }
        numbers.push(parsed);
      });
      if (numbers.length === values.length) out[name] = numbers;
      continue;
    }

    const raw = values[0];

    if (field.kind === "string") {
      out[name] = raw;
      continue;
    }

    if (field.kind === "bool") {
      const parsed = asBool(raw);
      if (parsed === null) {
        issues.push({
          path: name,
          code: "invalid_format",
          message: "expected true or false",
        });
        continue;
      }
      out[name] = parsed;
      continue;
    }

    const parsed = asInt(raw);
    if (parsed === null) {
      issues.push({
        path: name,
        code: "invalid_format",
        message: "expected an integer",
      });
      continue;
    }
    if (field.min !== undefined && parsed < field.min) {
      issues.push({
        path: name,
        code: "too_small",
        message: `must be at least ${field.min}`,
      });
      continue;
    }
    if (field.max !== undefined && parsed > field.max) {
      issues.push({
        path: name,
        code: "too_large",
        message: `must be at most ${field.max}`,
      });
      continue;
    }
    out[name] = parsed;
  }

  return issues.length === 0 ? { ok: true, value: out } : { ok: false, issues };
}

exercises.hints:
## Hint 1

This runs *before* the body is read, which is the whole reason it is a separate
function. Refusing an unsupported media type costs you a header lookup;
discovering it after buffering a megabyte costs you the megabyte. The previous
sector's ordering rule — cheap checks first — is what this exercise is
mechanising.

## Hint 2

Media type parsing is a split and a fold:

```ts
const [rawType, ...rest] = value.split(";");
const type = rawType.trim().toLowerCase();
const parameters: Record<string, string> = {};
for (const part of rest) {
  const eq = part.indexOf("=");
  if (eq === -1) return null;
  const name = part.slice(0, eq).trim().toLowerCase();
  const raw = part.slice(eq + 1).trim();
  parameters[name] = raw.startsWith('"') ? raw.slice(1, -1) : raw;
}
```

`indexOf("=")` rather than `split("=")` because a parameter value may itself
contain `=` — base64 padding in a boundary is the case that finds this bug.

## Hint 3

The suffix rule is from RFC 6839: a media type ending in `+json` uses JSON
syntax, so a JSON parser can read it. `application/vnd.api+json` (JSON:API),
`application/problem+json` and `application/ld+json` are all in this family.
Supporting the suffix is what lets a client send a more specific type without
you enumerating every vendor tree — but make it opt-in, because "I will parse
anything that ends in +json" is a decision, not a default.

