// v3nb03_validation_errors / ex3 - reference solution (author only).
export interface ParsedMediaType {
  type: string;
  parameters: Record<string, string>;
}

export function parseMediaType(value: string): ParsedMediaType | null {
  if (typeof value !== "string" || value.trim() === "") return null;

  const [rawType, ...rest] = value.split(";");
  const type = rawType.trim().toLowerCase();
  if (!/^[a-z0-9!#$%&'*+.^_`|~-]+\/[a-z0-9!#$%&'*+.^_`|~-]+$/.test(type)) {
    return null;
  }

  const parameters: Record<string, string> = {};
  for (const part of rest) {
    if (part.trim() === "") continue;
    // indexOf, not split: a boundary parameter can contain "=" padding.
    const eq = part.indexOf("=");
    if (eq === -1) return null;
    const name = part.slice(0, eq).trim().toLowerCase();
    if (name === "") return null;
    let raw = part.slice(eq + 1).trim();
    if (raw.startsWith('"') && raw.endsWith('"') && raw.length >= 2) {
      raw = raw.slice(1, -1);
    }
    // charset is case-insensitive by definition; other values are not.
    parameters[name] = name === "charset" ? raw.toLowerCase() : raw;
  }

  return { type, parameters };
}

export interface BodyCheckOptions {
  consumes: readonly string[];
  allowSuffix?: boolean;
}

export function checkRequestBody(
  headers: Record<string, string | string[] | undefined>,
  options: BodyCheckOptions,
):
  | { ok: true; type: string | null }
  | { ok: false; status: number; code: string } {
  const first = (name: string): string | undefined => {
    const value = headers[name];
    return Array.isArray(value) ? value[0] : value;
  };

  const length = first("content-length");
  const transfer = first("transfer-encoding");
  const hasBody =
    transfer !== undefined || (length !== undefined && Number(length) > 0);

  if (!hasBody) return { ok: true, type: null };

  const raw = first("content-type");
  if (raw === undefined || raw.trim() === "") {
    // Never sniff: accepting a body with no declared type is how a JSON
    // endpoint becomes CSRF-able from a plain HTML form.
    return { ok: false, status: 415, code: "missing_content_type" };
  }

  const parsed = parseMediaType(raw);
  if (parsed === null) {
    return { ok: false, status: 400, code: "malformed_content_type" };
  }

  const accepted =
    options.consumes.includes(parsed.type) ||
    (options.allowSuffix === true &&
      parsed.type.endsWith("+json") &&
      options.consumes.includes("application/json"));
  if (!accepted) {
    return { ok: false, status: 415, code: "unsupported_media_type" };
  }

  const charset = parsed.parameters.charset;
  if (charset !== undefined && charset !== "utf-8") {
    // Decoding non-UTF-8 bytes as UTF-8 corrupts data silently; refuse loudly.
    return { ok: false, status: 415, code: "unsupported_charset" };
  }

  return { ok: true, type: parsed.type };
}

