// v3nb03_validation_errors / ex4 - reference solution (author only).
export interface Issue {
  path: string;
  code: string;
  message: string;
}

export interface ProblemInit {
  type?: string;
  title: string;
  status: number;
  detail?: string;
  instance?: string;
  errors?: Issue[];
  extensions?: Record<string, unknown>;
}

const CORE = new Set([
  "type",
  "title",
  "status",
  "detail",
  "instance",
  "errors",
]);

export function problem(init: ProblemInit): {
  status: number;
  headers: Record<string, string>;
  body: string;
} {
  if (
    !Number.isInteger(init.status) ||
    init.status < 400 ||
    init.status > 599
  ) {
    // A programmer error: fail in the test suite, not in production.
    throw new TypeError(`problem status must be 400-599, got ${init.status}`);
  }

  const type = init.type ?? "about:blank";
  if (type !== "about:blank" && !URL.canParse(type)) {
    throw new TypeError(`problem type must be an absolute URI, got ${type}`);
  }

  // Insertion order is the serialised order for string keys, which keeps
  // diffs and snapshots readable.
  const document: Record<string, unknown> = { type, title: init.title, status: init.status };
  if (init.detail !== undefined) document.detail = init.detail;
  if (init.instance !== undefined) document.instance = init.instance;
  if (init.errors !== undefined && init.errors.length > 0) {
    document.errors = init.errors;
  }

  for (const [key, value] of Object.entries(init.extensions ?? {})) {
    if (CORE.has(key)) {
      throw new TypeError(`extension "${key}" collides with a core field`);
    }
    document[key] = value;
  }

  const body = JSON.stringify(document);
  return {
    status: init.status,
    headers: {
      "content-type": "application/problem+json; charset=utf-8",
      "content-length": String(Buffer.byteLength(body, "utf8")),
    },
    body,
  };
}

// v3nb03_validation_errors / ex5 - reference solution (author only).
export interface Issue {
  path: string;
  code: string;
  message: string;
}

export interface ProblemInit {
  type?: string;
  title: string;
  status: number;
  detail?: string;
  instance?: string;
  errors?: Issue[];
  extensions?: Record<string, unknown>;
}

const CORE = new Set(["type", "title", "status", "detail", "instance", "errors"]);

export function problem(init: ProblemInit): {
  status: number;
  headers: Record<string, string>;
  body: string;
} {
  if (!Number.isInteger(init.status) || init.status < 400 || init.status > 599) {
    throw new TypeError(`problem status must be 400-599, got ${init.status}`);
  }
  const type = init.type ?? "about:blank";
  if (type !== "about:blank" && !URL.canParse(type)) {
    throw new TypeError(`problem type must be an absolute URI, got ${type}`);
  }
  const document: Record<string, unknown> = {
    type,
    title: init.title,
    status: init.status,
  };
  if (init.detail !== undefined) document.detail = init.detail;
  if (init.instance !== undefined) document.instance = init.instance;
  if (init.errors !== undefined && init.errors.length > 0) {
    document.errors = init.errors;
  }
  for (const [key, value] of Object.entries(init.extensions ?? {})) {
    if (CORE.has(key)) {
      throw new TypeError(`extension "${key}" collides with a core field`);
    }
    document[key] = value;
  }
  const body = JSON.stringify(document);
  return {
    status: init.status,
    headers: {
      "content-type": "application/problem+json; charset=utf-8",
      "content-length": String(Buffer.byteLength(body, "utf8")),
    },
    body,
  };
}

export interface Entry {
  status: number;
  type: string;
  title: string;
}

export interface MapperOptions {
  requestId: () => string;
  report: (error: unknown) => void;
}

const GENERIC_DETAIL = "An unexpected error occurred.";

export function createErrorMapper(
  registry: Record<string, Entry>,
  options: MapperOptions,
): (error: unknown, instance?: string) => ReturnType<typeof problem> {
  return (error, instance) => {
    const code = (error as { code?: unknown } | null)?.code;
    // hasOwn, so a code of "constructor" cannot find a prototype member.
    const entry =
      typeof code === "string" && Object.hasOwn(registry, code)
        ? registry[code]
        : undefined;

    const status = entry?.status ?? 500;
    if (status >= 500) options.report(error);

    const rawIssues = (error as { issues?: unknown } | null)?.issues;
    const issues = Array.isArray(rawIssues) ? (rawIssues as Issue[]) : undefined;

    const message = (error as { message?: unknown } | null)?.message;

    return problem({
      type: entry?.type ?? "about:blank",
      title: entry?.title ?? "Internal Server Error",
      status,
      // Status class decides the detail, even for a REGISTERED 5xx: the
      // message underneath names hosts, tables and file paths.
      detail:
        status >= 500
          ? GENERIC_DETAIL
          : typeof message === "string"
            ? message
            : undefined,
      instance,
      errors: status >= 500 ? undefined : issues,
      extensions: { requestId: options.requestId() },
    });
  };
}

exercises.hints:
## Hint 1

The distinction the exercise is built on: a schema says *what a field is*, and
these rules say *what a document means*. No schema language can express "the
discount must not exceed a sum of products of two other fields", which is why
every real validator has a second phase and why that phase produces 422 rather
than 400.

## Hint 2

Duplicate detection with the right path needs the index, so a `Map` from value
to first index reads best:

```ts
const seen = new Map<string, number>();
order.items.forEach((item, i) => {
  if (seen.has(item.sku)) {
    issues.push({ path: `items[${i}].sku`, code: "duplicate_sku", ... });
    return;
  }
  seen.set(item.sku, i);
});
