// v3nb03_validation_errors / ex6 - reference solution (author only).
export interface Issue {
  path: string;
  code: string;
  message: string;
}

export interface Order {
  currency: string;
  items: Array<{ sku: string; quantity: number; unitPrice: number }>;
  discount: number;
  startsAt: string;
  endsAt: string;
}

const CURRENCIES = new Set(["GBP", "EUR", "USD"]);
const SYNTAX = new Set([
  "invalid_type",
  "required",
  "invalid_format",
  "invalid_json",
]);

export function checkOrder(order: Order): Issue[] {
  const issues: Issue[] = [];

  if (!CURRENCIES.has(order.currency)) {
    issues.push({
      path: "currency",
      code: "unsupported_currency",
      message: "must be GBP, EUR or USD",
    });
  }

  if (order.items.length === 0) {
    issues.push({
      path: "items",
      code: "empty_order",
      message: "must contain at least one item",
    });
  } else {
    const seen = new Map<string, number>();
    order.items.forEach((item, i) => {
      if (seen.has(item.sku)) {
        // The SECOND occurrence: the first is the one the user meant to keep.
        issues.push({
          path: `items[${i}].sku`,
          code: "duplicate_sku",
          message: "appears more than once in this order",
        });
        return;
      }
      seen.set(item.sku, i);
    });

    // Integer minor units throughout: no floating-point money, ever.
    const subtotal = order.items.reduce(
      (total, item) => total + item.quantity * item.unitPrice,
      0,
    );
    if (order.discount > subtotal) {
      issues.push({
        path: "discount",
        code: "discount_exceeds_total",
        message: "must not exceed the order subtotal",
      });
    }
  }

  const starts = Date.parse(order.startsAt);
  const ends = Date.parse(order.endsAt);
  if (Number.isNaN(starts)) {
    issues.push({
      path: "startsAt",
      code: "invalid_date",
      message: "is not a valid date",
    });
  }
  if (Number.isNaN(ends)) {
    issues.push({
      path: "endsAt",
      code: "invalid_date",
      message: "is not a valid date",
    });
  }
  if (!Number.isNaN(starts) && !Number.isNaN(ends) && ends <= starts) {
    issues.push({
      path: "endsAt",
      code: "end_before_start",
      message: "must be after startsAt",
    });
  }

  return issues;
}

export function statusFor(issues: ReadonlyArray<Issue>): number {
  if (issues.length === 0) return 200;
  // Understood-but-unacceptable is 422; not-understood is 400.
  return issues.some((issue) => SYNTAX.has(issue.code)) ? 400 : 422;
}

