export interface Issue {
  path: string;
  code: string;
  message: string;
}

export interface FieldRule {
  trim?: boolean;
  lower?: boolean;
  emptyAsAbsent?: boolean;
}

// Own properties with these names can end up on Object.prototype via a naive
// copy; never carry them across.
const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

export function sanitize(
  fields: Record<string, FieldRule>,
  input: Record<string, unknown>,
  options: { unknown: "strip" | "reject" },
): { value: Record<string, unknown>; issues: Issue[] } {
  const issues: Issue[] = [];
  const value: Record<string, unknown> = {};

  for (const key of FORBIDDEN) {
    if (Object.hasOwn(input, key)) {
      issues.push({
        path: key,
        code: "forbidden_key",
        message: "is not an acceptable property name",
      });
    }
  }

  // Build the output from the ALLOWLIST; never filter the input.
  for (const [key, rule] of Object.entries(fields)) {
    if (FORBIDDEN.has(key)) continue;
    if (!Object.hasOwn(input, key)) continue;

    let current = input[key];
    if (typeof current === "string") {
      // Transformations apply to strings only - no coercion of other types.
      if (rule.trim === true) current = current.trim();
      if (rule.lower === true) current = (current as string).toLowerCase();
      if (rule.emptyAsAbsent === true && (current as string) === "") continue;
    }
    value[key] = current;
  }

  if (options.unknown === "reject") {
    const undeclared = Object.keys(input)
      .filter((key) => !Object.hasOwn(fields, key) && !FORBIDDEN.has(key))
      .sort();
    for (const key of undeclared) {
      issues.push({
        path: key,
        code: "unknown_key",
        message: "is not a recognised field",
      });
    }
  }

  return { value, issues };
}

