export type Schema =
  | { kind: "string"; min?: number; max?: number; pattern?: RegExp }
  | { kind: "number"; int?: boolean; min?: number; max?: number }
  | { kind: "boolean" }
  | { kind: "array"; of: Schema; min?: number; max?: number }
  | { kind: "object"; fields: Record<string, Schema>; optional?: string[] };

export interface Issue {
  path: string;
  code: string;
  message: string;
}

export interface Limits {
  maxIssues: number;
  maxDepth: number;
  maxItems: number;
}

export function collectIssues(
  schema: Schema,
  value: unknown,
  limits: Limits,
): { issues: Issue[]; truncated: boolean } {
  const issues: Issue[] = [];
  const push = (path: string, code: string, message: string): void => {
    issues.push({ path, code, message });
  };

  const walk = (
    node: Schema,
    current: unknown,
    path: string,
    depth: number,
  ): void => {
    // One guard at the top of the step, not after every push.
    if (issues.length >= limits.maxIssues) return;
    if (depth > limits.maxDepth) {
      // Our own recursion is what a deeply nested payload overflows; JSON.parse
      // builds it happily.
      push(path, "too_deep", "is nested more deeply than allowed");
      return;
    }

    switch (node.kind) {
      case "string": {
        if (typeof current !== "string") {
          push(path, "invalid_type", "expected a string");
          return;
        }
        if (node.min !== undefined && current.length < node.min) {
          push(path, "too_small", `must be at least ${node.min} characters`);
        }
        if (node.max !== undefined && current.length > node.max) {
          push(path, "too_large", `must be at most ${node.max} characters`);
        }
        if (node.pattern !== undefined && !node.pattern.test(current)) {
          push(path, "invalid_format", "does not match the expected format");
        }
        return;
      }

      case "number": {
        if (typeof current !== "number" || !Number.isFinite(current)) {
          push(path, "invalid_type", "expected a finite number");
          return;
        }
        if (node.int === true && !Number.isInteger(current)) {
          push(path, "invalid_format", "must be a whole number");
        }
        if (node.min !== undefined && current < node.min) {
          push(path, "too_small", `must be at least ${node.min}`);
        }
        if (node.max !== undefined && current > node.max) {
          push(path, "too_large", `must be at most ${node.max}`);
        }
        return;
      }

      case "boolean": {
        if (typeof current !== "boolean") {
          push(path, "invalid_type", "expected a boolean");
        }
        return;
      }

      case "array": {
        if (!Array.isArray(current)) {
          push(path, "invalid_type", "expected an array");
          return;
        }
        if (node.min !== undefined && current.length < node.min) {
          push(path, "too_small", `must have at least ${node.min} items`);
        }
        if (node.max !== undefined && current.length > node.max) {
          push(path, "too_large", `must have at most ${node.max} items`);
        }
        if (current.length > limits.maxItems) {
          push(path, "too_many_items", `must have at most ${limits.maxItems} items`);
        }
        const upTo = Math.min(current.length, limits.maxItems);
        for (let i = 0; i < upTo; i += 1) {
          if (issues.length >= limits.maxIssues) return;
          walk(node.of, current[i], `${path}[${i}]`, depth + 1);
        }
        return;
      }

      case "object": {
        if (typeof current !== "object" || current === null || Array.isArray(current)) {
          push(path, "invalid_type", "expected an object");
          return;
        }
        const record = current as Record<string, unknown>;
        for (const [key, field] of Object.entries(node.fields)) {
          if (issues.length >= limits.maxIssues) return;
          const child = path === "" ? key : `${path}.${key}`;
          const present = Object.hasOwn(record, key) && record[key] !== undefined;
          if (!present) {
            if (node.optional?.includes(key) !== true) {
              push(child, "required", "is required");
            }
            continue;
          }
          walk(field, record[key], child, depth + 1);
        }
        return;
      }
    }
  };

  walk(schema, value, "", 0);

  const truncated = issues.length >= limits.maxIssues;
  if (truncated) {
    // Not counted against the cap, and added exactly once.
    issues.push({
      path: "",
      code: "truncated",
      message: `only the first ${limits.maxIssues} problems are reported`,
    });
  }
  return { issues, truncated };
}

