import type { IncomingMessage, ServerResponse } from "node:http";

export interface Issue {
  path: string;
  code: string;
  message: string;
}

interface Problem {
  status: number;
  headers: Record<string, string>;
  body: string;
}

const BODY_LIMIT = 16384;
const CURRENCIES = new Set(["GBP", "EUR", "USD"]);
const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);
const DECLARED = ["currency", "items", "discount", "startsAt", "endsAt"];

function problem(init: {
  type?: string;
  title: string;
  status: number;
  detail?: string;
  instance?: string;
  errors?: Issue[];
  extensions?: Record<string, unknown>;
}): Problem {
  const document: Record<string, unknown> = {
    type: init.type ?? "about:blank",
    title: init.title,
    status: init.status,
  };
  if (init.detail !== undefined) document.detail = init.detail;
  if (init.instance !== undefined) document.instance = init.instance;
  if (init.errors !== undefined && init.errors.length > 0) {
    document.errors = init.errors;
  }
  for (const [key, value] of Object.entries(init.extensions ?? {})) {
    document[key] = value;
  }
  const body = JSON.stringify(document);
  return {
    status: init.status,
    headers: {
      "content-type": "application/problem+json; charset=utf-8",
      "content-length": String(Buffer.byteLength(body, "utf8")),
    },
    body,
  };
}

function mediaTypeGate(
  req: IncomingMessage,
): { ok: true } | { ok: false; status: number; code: string; title: string } {
  const length = req.headers["content-length"];
  const hasBody =
    req.headers["transfer-encoding"] !== undefined ||
    (length !== undefined && Number(length) > 0);
  if (!hasBody) {
    return { ok: false, status: 400, code: "invalid_json", title: "Bad Request" };
  }

  const raw = req.headers["content-type"];
  if (typeof raw !== "string" || raw.trim() === "") {
    return {
      ok: false,
      status: 415,
      code: "missing_content_type",
      title: "Unsupported Media Type",
    };
  }
  const [rawType, ...rest] = raw.split(";");
  const type = rawType.trim().toLowerCase();
  if (type !== "application/json" && !type.endsWith("+json")) {
    return {
      ok: false,
      status: 415,
      code: "unsupported_media_type",
      title: "Unsupported Media Type",
    };
  }
  for (const part of rest) {
    const eq = part.indexOf("=");
    if (eq === -1) continue;
    if (part.slice(0, eq).trim().toLowerCase() !== "charset") continue;
    if (part.slice(eq + 1).trim().toLowerCase().replace(/"/g, "") !== "utf-8") {
      return {
        ok: false,
        status: 415,
        code: "unsupported_charset",
        title: "Unsupported Media Type",
      };
    }
  }
  return { ok: true };
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const declared = Number(req.headers["content-length"]);
  if (Number.isFinite(declared) && declared > BODY_LIMIT) {
    throw Object.assign(new Error("too large"), { code: "payload_too_large" });
  }
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    if (size > BODY_LIMIT) {
      req.destroy();
      throw Object.assign(new Error("too large"), { code: "payload_too_large" });
    }
    chunks.push(buf);
  }
  return Buffer.concat(chunks);
}

function checkShape(body: Record<string, unknown>): Issue[] {
  const issues: Issue[] = [];
  const push = (path: string, code: string, message: string) =>
    issues.push({ path, code, message });

  const currency = body.currency;
  if (typeof currency !== "string") push("currency", "invalid_type", "expected a string");
  else if (currency.length !== 3) push("currency", "invalid_format", "must be 3 letters");

  const discount = body.discount;
  if (typeof discount !== "number" || !Number.isInteger(discount)) {
    push("discount", "invalid_type", "expected an integer");
  } else if (discount < 0) push("discount", "too_small", "must be at least 0");

  for (const key of ["startsAt", "endsAt"]) {
    if (typeof body[key] !== "string") push(key, "invalid_type", "expected a string");
