  if (Number.isNaN(starts)) {
    issues.push({ path: "startsAt", code: "invalid_date", message: "is not a valid date" });
  }
  if (Number.isNaN(ends)) {
    issues.push({ path: "endsAt", code: "invalid_date", message: "is not a valid date" });
  }
  if (!Number.isNaN(starts) && !Number.isNaN(ends) && ends <= starts) {
    issues.push({ path: "endsAt", code: "end_before_start", message: "must be after startsAt" });
  }
  return issues;
}

export function createOrdersHandler(deps: {
  requestId: () => string;
  report: (error: unknown) => void;
}): (req: IncomingMessage, res: ServerResponse) => void {
  let nextOrder = 0;

  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    const instance = url.pathname;
    const extensions = () => ({ requestId: deps.requestId() });

    const write = (p: Problem): void => {
      if (res.headersSent) {
        res.destroy();
        return;
      }
      res.writeHead(p.status, p.headers);
      res.end(p.body);
    };

    if (req.method !== "POST" || url.pathname !== "/orders") {
      write(problem({
        title: "Not Found",
        status: 404,
        instance,
        extensions: extensions(),
      }));
      return;
    }

    const gate = mediaTypeGate(req);
    if (!gate.ok) {
      write(problem({
        title: gate.title,
        status: gate.status,
        detail: gate.code,
        instance,
        extensions: extensions(),
      }));
      return;
    }

    void (async () => {
      const buffer = await readBody(req);

      let parsed: unknown;
      try {
        parsed = JSON.parse(buffer.toString("utf8"));
      } catch {
        write(problem({
          title: "Bad Request",
          status: 400,
          detail: "invalid_json",
          instance,
          extensions: extensions(),
        }));
        return;
      }

      if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
        write(problem({
          title: "Bad Request",
          status: 400,
          detail: "invalid_type",
          instance,
          extensions: extensions(),
        }));
        return;
      }

      const body = parsed as Record<string, unknown>;

      const shape = checkShape(body);
      if (shape.length > 0) {
        write(problem({
          title: "Validation failed",
          status: 422,
          detail: `${shape.length} field(s) were rejected`,
          instance,
          errors: shape,
          extensions: extensions(),
        }));
        return;
      }

      const unknownKeys = Object.keys(body)
        .filter((key) => !DECLARED.includes(key) && !FORBIDDEN.has(key))
        .sort()
        .map((key) => ({
          path: key,
          code: "unknown_key",
          message: "is not a recognised field",
        }));
      if (unknownKeys.length > 0) {
        write(problem({
          title: "Validation failed",
          status: 422,
          detail: `${unknownKeys.length} unknown field(s)`,
          instance,
          errors: unknownKeys,
          extensions: extensions(),
        }));
        return;
      }

      const semantic = checkSemantics(body);
      if (semantic.length > 0) {
        write(problem({
          title: "Validation failed",
          status: 422,
          detail: `${semantic.length} rule(s) were violated`,
          instance,
          errors: semantic,
          extensions: extensions(),
        }));
        return;
      }

      const items = body.items as Array<{ quantity: number; unitPrice: number }>;
      const subtotal = items.reduce((t, i) => t + i.quantity * i.unitPrice, 0);
      const id = `ord-${(nextOrder += 1)}`;
      const payload = Buffer.from(
        JSON.stringify({ id, subtotal, total: subtotal - (body.discount as number) }),
        "utf8",
      );
      res.writeHead(201, {
        "content-type": "application/json; charset=utf-8",
        "content-length": payload.length,
        // Relative reference: no need to trust the Host header.
        location: `/orders/${id}`,
      });
      res.end(payload);
    })().catch((error: unknown) => {
      const code = (error as { code?: unknown } | null)?.code;
      if (code === "payload_too_large") {
        write(problem({
          title: "Payload Too Large",
          status: 413,
          detail: "payload_too_large",
          instance,
          extensions: extensions(),
        }));
        return;
      }
      deps.report(error);
      write(problem({
        title: "Internal Server Error",
        status: 500,
        detail: "An unexpected error occurred.",
        instance,
        extensions: extensions(),
      }));
    });
  };
}

// v3nb03_validation_errors / review1 - reference solution (author only).
export interface Issue {
  path: string;
  code: string;
  message: string;
}

const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

function humanise(name: string): string {
  const words = name.replace(/([a-z0-9])([A-Z])/g, "$1 $2").toLowerCase();
  return words.charAt(0).toUpperCase() + words.slice(1);
}

export function explainIssue(issue: Issue): string {
  const { path, message } = issue;

  let label: string;
  if (path === "") {
    label = "This request";
  } else {
    const last = path.split(".").at(-1) as string;
    const indexed = /^(.*)\[(\d+)\]$/.exec(last);
    if (indexed !== null && indexed[1] !== "") {
      // "items[2]" - the element itself, spoken one-based.
      label = `${humanise(indexed[1]).replace(/s$/, "")} ${Number(indexed[2]) + 1}`;
    } else {
      const container = /\[(\d+)\]/.exec(path);
      label =
        container === null
          ? humanise(last)
          : `${humanise(last)} (item ${Number(container[1]) + 1})`;
    }
  }

  const sentence = `${label} ${message}`;
  return /[.!?]$/.test(sentence) ? sentence : `${sentence}.`;
}

export function fieldErrors(
  issues: ReadonlyArray<Issue>,
): Record<string, string[]> {
  // No prototype to pollute, whatever the paths turn out to be.
  const grouped = Object.create(null) as Record<string, string[]>;
  for (const issue of issues) {
    if (FORBIDDEN.has(issue.path)) continue;
    const bucket = (grouped[issue.path] ??= []);
    // Two layers can legitimately produce the same sentence; a form showing it
    // twice looks broken.
    if (!bucket.includes(issue.message)) bucket.push(issue.message);
  }
  return grouped;
}

