import { createHash, timingSafeEqual } from "node:crypto";

export function safeEqual(a: string, b: string): boolean {
  // Hash first: timingSafeEqual throws on a length mismatch, which is exactly
  // what a truncated token produces.
  const digest = (value: string): Buffer =>
    createHash("sha256").update(value, "utf8").digest();
  return timingSafeEqual(digest(a), digest(b));
}

function quote(value: string): string {
  return `"${value.replace(/([\\"])/g, "\\$1")}"`;
}

export function bearerChallenge(init: {
  realm: string;
  error?: string;
  description?: string;
}): string {
  const parts = [`realm=${quote(init.realm)}`];
  if (init.error !== undefined) parts.push(`error=${quote(init.error)}`);
  if (init.description !== undefined) {
    parts.push(`error_description=${quote(init.description)}`);
  }
  return `Bearer ${parts.join(", ")}`;
}

export function authenticateBearer(
  authorization: string | undefined,
  tokens: ReadonlyArray<string>,
):
  | { ok: true; token: string }
  | { ok: false; status: 401; code: string; headers: Record<string, string> } {
  const deny = (code: string, error?: string, description?: string) =>
    ({
      ok: false as const,
      status: 401 as const,
      code,
      headers: {
        "www-authenticate": bearerChallenge({
          realm: "api",
          error,
          description,
        }),
      },
    });

  if (authorization === undefined || authorization.trim() === "") {
    // No error parameter: the bare challenge invites credentials.
    return deny("missing_token");
  }

  const space = authorization.indexOf(" ");
  const scheme = space === -1 ? authorization : authorization.slice(0, space);
  const token = space === -1 ? "" : authorization.slice(space + 1).trim();

  if (scheme.toLowerCase() !== "bearer" || token === "") {
    return deny("invalid_request", "invalid_request", "expected Bearer <token>");
  }

  // Accumulate rather than short-circuit, so every candidate is compared.
  let found = false;
  for (const candidate of tokens) found = safeEqual(candidate, token) || found;
  if (!found) {
    return deny("invalid_token", "invalid_token", "the token is not valid");
  }

  return { ok: true, token };
}

// v3nb04_auth_sessions_tokens / ex2 - reference solution (author only).
import { randomBytes, scrypt, timingSafeEqual } from "node:crypto";
import { promisify } from "node:util";

interface Params {
  N: number;
  r: number;
  p: number;
}

const DEFAULTS: Params = { N: 16384, r: 8, p: 1 };
const KEY_LENGTH = 64;

const derive = promisify(scrypt) as (
  password: string,
  salt: Buffer,
  keylen: number,
  options: { N: number; r: number; p: number; maxmem: number },
) => Promise<Buffer>;

async function kdf(
  password: string,
  salt: Buffer,
  params: Params,
): Promise<Buffer> {
  return derive(password.normalize("NFKC"), salt, KEY_LENGTH, {
    ...params,
    // Node's default maxmem (32 MB) is below 128 * N * r for larger costs.
    maxmem: 256 * params.N * params.r,
  });
}

export async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(16);
  const key = await kdf(password, salt, DEFAULTS);
  // The parameters travel WITH the hash, so the cost can be raised later.
  return [
    "scrypt",
    DEFAULTS.N,
    DEFAULTS.r,
    DEFAULTS.p,
    salt.toString("base64url"),
    key.toString("base64url"),
  ].join("$");
}

export async function verifyPassword(
  stored: string,
  password: string,
): Promise<boolean> {
  const parts = typeof stored === "string" ? stored.split("$") : [];
  if (parts.length !== 6 || parts[0] !== "scrypt") return false;

  const [, rawN, rawR, rawP, rawSalt, rawKey] = parts;
  const params = { N: Number(rawN), r: Number(rawR), p: Number(rawP) };
  if (!Object.values(params).every((v) => Number.isInteger(v) && v > 0)) {
    return false;
  }

  try {
    const salt = Buffer.from(rawSalt, "base64url");
    const expected = Buffer.from(rawKey, "base64url");
    if (expected.length !== KEY_LENGTH) return false;
    const actual = await kdf(password, salt, params);
    return timingSafeEqual(actual, expected);
  } catch {
    // Fail closed: a hash we cannot parse is a denial, not a 500.
    return false;
  }
}

// A real hash of a random string, so the missing-user path costs the same.
let dummy: Promise<string> | undefined;
function dummyHash(): Promise<string> {
  dummy ??= hashPassword(randomBytes(32).toString("base64url"));
  return dummy;
}

export async function verifyLogin(
  record: string | undefined,
  password: string,
): Promise<boolean> {
  const target = record ?? (await dummyHash());
  const ok = await verifyPassword(target, password);
  // Same work either way: an early return here enumerates your users.
  return record !== undefined && ok;
}

// v3nb04_auth_sessions_tokens / ex3 - reference solution (author only).
import { createHmac, timingSafeEqual } from "node:crypto";

export interface Key {
  id: string;
  secret: string;
}

export type Unsigned =
  | { ok: true; value: string; kid: string }
  | { ok: false; reason: "malformed" | "unknown_key" | "bad_signature" };

export function createSigner(keys: ReadonlyArray<Key>): {
  sign: (value: string) => string;
  unsign: (token: string) => Unsigned;
} {
  if (keys.length === 0) throw new TypeError("createSigner needs at least one key");
  const ring = new Map(keys.map((key) => [key.id, key.secret]));

  const mac = (secret: string, kid: string, payload: string): Buffer =>
    // The kid is INSIDE the signed material, so a token cannot be relabelled.
    createHmac("sha256", secret).update(`${kid}.${payload}`).digest();

  return {
    sign(value) {
      const key = keys[0];
      // base64url has no ".", so a value containing one cannot break the format.
      const payload = Buffer.from(value, "utf8").toString("base64url");
      const tag = mac(key.secret, key.id, payload).toString("base64url");
      return `${key.id}.${payload}.${tag}`;
    },

    unsign(token) {
      const parts = typeof token === "string" ? token.split(".") : [];
      if (parts.length !== 3 || parts.some((p) => p === "")) {
        return { ok: false, reason: "malformed" };
      }
      const [kid, payload, tag] = parts;

      const secret = ring.get(kid);
      if (secret === undefined) return { ok: false, reason: "unknown_key" };

      const expected = mac(secret, kid, payload);
      const actual = Buffer.from(tag, "base64url");
      // Length first: Buffer.from on garbage returns a short buffer, and
      // timingSafeEqual throws on a length mismatch.
      if (actual.length !== expected.length || !timingSafeEqual(actual, expected)) {
        return { ok: false, reason: "bad_signature" };
      }

      return {
        ok: true,
        value: Buffer.from(payload, "base64url").toString("utf8"),
        kid,
      };
    },
  };
}

// v3nb04_auth_sessions_tokens / ex4 - reference solution (author only).
export interface CookieAttributes {
  maxAge?: number;
  expires?: Date;
  domain?: string;
  path?: string;
  secure?: boolean;
  httpOnly?: boolean;
  sameSite?: "Lax" | "Strict" | "None";
}

const NAME = /^[A-Za-z0-9!#$%&'*+\-.^_`|~]+$/;

export function serializeCookie(
  name: string,
  value: string,
  attributes: CookieAttributes = {},
): string {
  if (!NAME.test(name)) throw new TypeError(`invalid cookie name: ${name}`);

  // Browser-enforced prefixes. Violating them means the cookie is silently
  // not stored, which presents as "works locally, not in staging".
  if (name.startsWith("__Host-")) {
    if (attributes.secure !== true) throw new TypeError("__Host- requires Secure");
    if (attributes.path !== "/") throw new TypeError("__Host- requires Path=/");
    if (attributes.domain !== undefined) {
      throw new TypeError("__Host- forbids Domain");
    }
  } else if (name.startsWith("__Secure-") && attributes.secure !== true) {
    throw new TypeError("__Secure- requires Secure");
  }

  if (attributes.sameSite === "None" && attributes.secure !== true) {
    throw new TypeError("SameSite=None requires Secure");
  }
  if (attributes.maxAge !== undefined && !Number.isInteger(attributes.maxAge)) {
    throw new TypeError("Max-Age must be an integer");
  }
  if (
    attributes.expires !== undefined &&
    Number.isNaN(attributes.expires.getTime())
  ) {
    throw new TypeError("Expires must be a valid Date");
  }

  const parts = [`${name}=${encodeURIComponent(value)}`];
  if (attributes.maxAge !== undefined) parts.push(`Max-Age=${attributes.maxAge}`);
  if (attributes.expires !== undefined) {
    parts.push(`Expires=${attributes.expires.toUTCString()}`);
  }
  if (attributes.domain !== undefined) parts.push(`Domain=${attributes.domain}`);
  if (attributes.path !== undefined) parts.push(`Path=${attributes.path}`);
  if (attributes.secure === true) parts.push("Secure");
  if (attributes.httpOnly === true) parts.push("HttpOnly");
  if (attributes.sameSite !== undefined) {
    parts.push(`SameSite=${attributes.sameSite}`);
  }
  return parts.join("; ");
}

export function parseCookies(header: string | undefined): Record<string, string> {
  const out: Record<string, string> = {};
  if (typeof header !== "string" || header.trim() === "") return out;

  for (const pair of header.split(";")) {
    const eq = pair.indexOf("=");
    if (eq === -1) continue;
    const name = pair.slice(0, eq).trim();
    if (name === "") continue;
    // First occurrence wins, and it is documented: servers that disagree about
    // this are the basis of cookie-shadowing attacks.
    if (Object.hasOwn(out, name)) continue;

    let raw = pair.slice(eq + 1).trim();
    if (raw.startsWith('"') && raw.endsWith('"') && raw.length >= 2) {
      raw = raw.slice(1, -1);
    }
    try {
      out[name] = decodeURIComponent(raw);
    } catch {
      // %zz is free for an attacker to send; it must not become a 500.
      continue;
    }
  }
  return out;
}

