// v3nb04_auth_sessions_tokens / ex5 - reference solution (author only).
import { createHmac, timingSafeEqual } from "node:crypto";

const b64url = (value: Buffer | string): string =>
  (Buffer.isBuffer(value) ? value : Buffer.from(value, "utf8")).toString("base64url");

function mac(secret: string, signingInput: string): Buffer {
  return createHmac("sha256", secret).update(signingInput).digest();
}

export function signJwt(
  claims: Record<string, unknown>,
  opts: { secret: string; kid?: string; now: number; ttlSeconds: number },
): string {
  const header: Record<string, unknown> = { alg: "HS256", typ: "JWT" };
  if (opts.kid !== undefined) header.kid = opts.kid;

  // Seconds, not milliseconds - the single most common JWT bug.
  const iat = Math.floor(opts.now / 1000);
  const payload = { ...claims, iat, exp: iat + opts.ttlSeconds };

  const signingInput = `${b64url(JSON.stringify(header))}.${b64url(JSON.stringify(payload))}`;
  return `${signingInput}.${mac(opts.secret, signingInput).toString("base64url")}`;
}

export function verifyJwt(
  token: string,
  opts: {
    secret: string;
    now: number;
    skewSeconds?: number;
    issuer?: string;
    audience?: string;
  },
): { ok: true; claims: Record<string, unknown> } | { ok: false; code: string } {
  const skew = opts.skewSeconds ?? 60;
  const parts = typeof token === "string" ? token.split(".") : [];
  if (parts.length !== 3 || parts.some((p) => p === "")) {
    return { ok: false, code: "malformed" };
  }
  const [h, p, s] = parts;

  let header: Record<string, unknown>;
  let claims: Record<string, unknown>;
  try {
    header = JSON.parse(Buffer.from(h, "base64url").toString("utf8")) as Record<string, unknown>;
    claims = JSON.parse(Buffer.from(p, "base64url").toString("utf8")) as Record<string, unknown>;
  } catch {
    return { ok: false, code: "malformed" };
  }
  if (typeof header !== "object" || header === null) {
    return { ok: false, code: "malformed" };
  }

  // WE decide the algorithm. Reading alg to choose a verifier is how
  // "alg: none" and RS256-to-HS256 confusion work.
  if (header.alg !== "HS256") return { ok: false, code: "unexpected_alg" };

  const tag = mac(opts.secret, `${h}.${p}`);
  const actual = Buffer.from(s, "base64url");
  // Length first: Buffer.from on garbage returns a short buffer, and
  // timingSafeEqual throws on a length mismatch.
  if (actual.length !== tag.length || !timingSafeEqual(actual, tag)) {
    return { ok: false, code: "bad_signature" };
  }

  // Only now are the claims trustworthy enough to read.
  const nowSeconds = Math.floor(opts.now / 1000);

  const exp = claims.exp;
  if (typeof exp !== "number" || !Number.isFinite(exp)) {
    return { ok: false, code: "missing_exp" };
  }
  if (exp + skew < nowSeconds) return { ok: false, code: "expired" };

  const nbf = claims.nbf;
  if (typeof nbf === "number" && nbf - skew > nowSeconds) {
    return { ok: false, code: "not_yet_valid" };
  }

  if (opts.issuer !== undefined && claims.iss !== opts.issuer) {
    return { ok: false, code: "wrong_issuer" };
  }
  if (opts.audience !== undefined) {
    const aud = claims.aud;
    const matches = Array.isArray(aud)
      ? aud.includes(opts.audience)
      : aud === opts.audience;
    if (!matches) return { ok: false, code: "wrong_audience" };
  }

  return { ok: true, claims };
}

// v3nb04_auth_sessions_tokens / ex6 - reference solution (author only).
export interface Session {
  userId: string;
  createdAt: number;
  lastSeenAt: number;
}

export interface StoreOptions {
  now: () => number;
  newId: () => string;
  idleMs: number;
  absoluteMs: number;
}

export function createSessionStore(options: StoreOptions): {
  start: (userId: string, previousId?: string) => string;
  get: (id: string) => Session | null;
  touch: (id: string) => Session | null;
  destroy: (id: string) => boolean;
  sweep: () => number;
  size: () => number;
} {
  const sessions = new Map<string, Session>();

  // One predicate, used everywhere: three inlined copies drift.
  const expired = (session: Session, at: number): boolean =>
    at >= session.lastSeenAt + options.idleMs ||
    at >= session.createdAt + options.absoluteMs;

  const read = (id: string): Session | null => {
    const session = sessions.get(id);
    if (session === undefined) return null;
    if (expired(session, options.now())) {
      sessions.delete(id);
      return null;
    }
    return session;
  };

  return {
    start(userId, previousId) {
      // A new id at every privilege change: the entire fixation defence.
      if (previousId !== undefined) sessions.delete(previousId);
      const id = options.newId();
      const at = options.now();
      sessions.set(id, { userId, createdAt: at, lastSeenAt: at });
      return id;
    },

    get(id) {
      return read(id);
    },

    touch(id) {
      const session = read(id);
      if (session === null) return null;
      // Slide the idle window only. Moving createdAt would collapse the two
      // deadlines into the weaker one.
      session.lastSeenAt = options.now();
      return session;
    },

    destroy(id) {
      return sessions.delete(id);
    },

    sweep() {
      const at = options.now();
      let removed = 0;
      for (const [id, session] of sessions) {
        if (expired(session, at)) {
          sessions.delete(id);
          removed += 1;
        }
      }
      return removed;
    },

    size() {
      return sessions.size;
    },
  };
}

// v3nb04_auth_sessions_tokens / ex7 - reference solution (author only).
import { createHash } from "node:crypto";

interface Record_ {
  familyId: string;
  userId: string;
  issuedAt: number;
  used: boolean;
}

export type RotateResult =
  | { ok: true; token: string; familyId: string }
  | {
      ok: false;
      reason: "unknown" | "revoked" | "reuse_detected" | "expired";
      familyId?: string;
    };

export function createRefreshStore(options: {
  now: () => number;
  newToken: () => string;
  ttlMs: number;
}): {
  issue: (userId: string) => { token: string; familyId: string };
  rotate: (token: string) => RotateResult;
  revokeFamily: (familyId: string) => boolean;
  size: () => number;
} {
  const records = new Map<string, Record_>();
  const families = new Map<string, { revoked: boolean }>();

  // High-entropy random needs no salt and no slow KDF - there is no dictionary
  // to attack. It still must not be stored in a usable form.
  const digest = (token: string): string =>
    createHash("sha256").update(token, "utf8").digest("hex");

  const mint = (userId: string, familyId: string): string => {
    const token = options.newToken();
    records.set(digest(token), {
      familyId,
      userId,
      issuedAt: options.now(),
      used: false,
    });
    return token;
  };

  const revoke = (familyId: string): void => {
    const family = families.get(familyId);
    if (family !== undefined) family.revoked = true;
    for (const [hash, record] of records) {
      if (record.familyId === familyId) records.delete(hash);
    }
  };

  return {
    issue(userId) {
      const familyId = `fam-${families.size + 1}`;
      families.set(familyId, { revoked: false });
      return { token: mint(userId, familyId), familyId };
    },

    rotate(token) {
      const hash = digest(token);
      const record = records.get(hash);
      if (record === undefined) return { ok: false, reason: "unknown" };

      // Revoked first: it is the fact an operator needs from the logs.
      if (families.get(record.familyId)?.revoked === true) {
        return { ok: false, reason: "revoked", familyId: record.familyId };
      }

      if (record.used) {
        // Either a dropped response or a thief; you cannot tell, so assume the
        // worse one and burn the family.
        revoke(record.familyId);
        return {
          ok: false,
          reason: "reuse_detected",
          familyId: record.familyId,
        };
      }

      if (options.now() - record.issuedAt >= options.ttlMs) {
        return { ok: false, reason: "expired", familyId: record.familyId };
      }

      record.used = true;
      return {
        ok: true,
        token: mint(record.userId, record.familyId),
        familyId: record.familyId,
      };
    },

    revokeFamily(familyId) {
      if (!families.has(familyId)) return false;
      revoke(familyId);
      return true;
    },

    size() {
      return records.size;
    },
  };
}

