// v3nb04_auth_sessions_tokens / ex8 - reference solution (author only).
export interface Principal {
  id: string;
  roles: string[];
  scopes: string[];
}

export interface Policy {
  scope?: string;
  roles?: string[];
  ownership?: boolean;
}

export type Decision =
  | { ok: true }
  | {
      ok: false;
      status: 401 | 403;
      code: string;
      headers?: Record<string, string>;
    };

export function createAuthorizer(
  policies: Record<string, Policy>,
): (
  principal: Principal | null,
  action: string,
  resource?: { ownerId?: string },
) => Decision {
  return (principal, action, resource) => {
    // Identity first: 401 means "I do not know who you are".
    if (principal === null) {
      return {
        ok: false,
        status: 401,
        code: "unauthenticated",
        headers: { "www-authenticate": 'Bearer realm="api"' },
      };
    }

    // Fail closed: an action nobody wrote a rule for is not permitted.
    if (!Object.hasOwn(policies, action)) {
      return { ok: false, status: 403, code: "forbidden" };
    }
    const policy = policies[action];

    if (policy.scope !== undefined && !principal.scopes.includes(policy.scope)) {
      return {
        ok: false,
        status: 403,
        code: "insufficient_scope",
        headers: {
          // RFC 6750 puts insufficient_scope on a 403, not a 401.
          "www-authenticate": `Bearer realm="api", error="insufficient_scope", scope="${policy.scope}"`,
        },
      };
    }

    if (
      policy.roles !== undefined &&
      !policy.roles.some((role) => principal.roles.includes(role))
    ) {
      return { ok: false, status: 403, code: "forbidden" };
    }

    if (policy.ownership === true) {
      // The bypass relaxes ownership only - never scope, never roles.
      const isAdmin = principal.roles.includes("admin");
      if (!isAdmin && resource?.ownerId !== principal.id) {
        return { ok: false, status: 403, code: "not_owner" };
      }
    }

    return { ok: true };
  };
}

// v3nb04_auth_sessions_tokens / challenge - reference solution (author only).
import { createHash, timingSafeEqual } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";

export interface Deps {
  users: Map<string, { id: string; hash: string }>;
  verifyLogin: (record: string | undefined, password: string) => Promise<boolean>;
  sign: (value: string) => string;
  unsign: (token: string) => { ok: true; value: string } | { ok: false };
  newId: () => string;
  newCsrf: () => string;
  now: () => number;
}

const SID = "__Host-sid";
const CSRF = "__Host-csrf";
const MAX_AGE = 1800;

function safeEqual(a: string, b: string): boolean {
  const digest = (v: string) => createHash("sha256").update(v, "utf8").digest();
  return timingSafeEqual(digest(a), digest(b));
}

function parseCookies(header: string | undefined): Record<string, string> {
  const out: Record<string, string> = {};
  if (typeof header !== "string") return out;
  for (const pair of header.split(";")) {
    const eq = pair.indexOf("=");
    if (eq === -1) continue;
    const name = pair.slice(0, eq).trim();
    if (name === "" || Object.hasOwn(out, name)) continue;
    try {
      out[name] = decodeURIComponent(pair.slice(eq + 1).trim());
    } catch {
      continue;
    }
  }
  return out;
}

function cookie(name: string, value: string, maxAge: number, httpOnly: boolean): string {
  const parts = [
    `${name}=${encodeURIComponent(value)}`,
    `Max-Age=${maxAge}`,
    "Path=/",
    "Secure",
    "SameSite=Lax",
  ];
  if (httpOnly) parts.splice(4, 0, "HttpOnly");
  return parts.join("; ");
}

export function createAuthApp(deps: Deps): (req: IncomingMessage, res: ServerResponse) => void {
  const sessions = new Map<string, { userId: string; startedAt: number }>();

  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    const method = (req.method ?? "GET").toUpperCase();
