        const body = (await readBody()) as { email?: unknown; password?: unknown } | undefined;
        const email = typeof body?.email === "string" ? body.email : "";
        const password = typeof body?.password === "string" ? body.password : "";
        const record = deps.users.get(email);

        // Same work, same answer, whether or not the user exists.
        const ok = await deps.verifyLogin(record?.hash, password);
        if (!ok || record === undefined) {
          send(401, { error: "invalid_credentials" });
          return;
        }

