        const id = currentSessionId();
        const session = id === null ? undefined : sessions.get(id);
        if (session === undefined) {
          res.setHeader("www-authenticate", 'Cookie realm="api"');
          send(401, { error: "unauthenticated" });
          return;
        }
        send(200, { userId: session.userId });
        return;
      }

      if (method === "POST" && url.pathname === "/profile") {
        const id = currentSessionId();
        const session = id === null ? undefined : sessions.get(id);
        if (session === undefined) {
          res.setHeader("www-authenticate", 'Cookie realm="api"');
          send(401, { error: "unauthenticated" });
          return;
        }
        const header = req.headers["x-csrf-token"];
        const sent = typeof header === "string" ? header : "";
        const stored = cookies[CSRF] ?? "";
        if (sent === "" || stored === "" || !safeEqual(sent, stored)) {
          send(403, { error: "csrf_failed" });
          return;
        }
        send(204, undefined);
        return;
      }

      if (method === "POST" && url.pathname === "/logout") {
        const id = currentSessionId();
        if (id !== null) sessions.delete(id);
        // Same name, path and attributes, or the browser keeps the old one.
        res.appendHeader("set-cookie", cookie(SID, "", 0, true));
        res.appendHeader("set-cookie", cookie(CSRF, "", 0, false));
        send(204, undefined);
        return;
      }

      send(404, { error: "not_found" });
    })().catch(() => {
      if (!res.headersSent) send(500, { error: "internal_error" });
    });
  };
}

