export type Credentials =
  | { scheme: "basic"; user: string; password: string }
  | { scheme: "bearer"; token: string }
  | { scheme: "other"; name: string; parameters: string };

const TOKEN68 = /^[A-Za-z0-9\-._~+/]+=*$/;
const BASE64 = /^[A-Za-z0-9+/]+={0,2}$/;

export function parseAuthorization(
  header: string | undefined,
): Credentials | null {
  if (typeof header !== "string") return null;
  // One split on the first run of whitespace; the remainder stays verbatim,
  // because schemes like Digest carry parameters containing spaces.
  const match = /^\s*(\S+)\s+(.*?)\s*$/.exec(header);
  if (match === null) return null;

  const [, name, parameters] = match;
  if (parameters === "") return null;
  const scheme = name.toLowerCase();

  if (scheme === "bearer") {
    // Bounding the charset at the parse boundary is cheaper than sanitising
    // at every later use.
    if (!TOKEN68.test(parameters)) return null;
    return { scheme: "bearer", token: parameters };
  }

  if (scheme === "basic") {
    if (!BASE64.test(parameters) || parameters.length % 4 !== 0) return null;
    const decoded = Buffer.from(parameters, "base64").toString("utf8");
    const colon = decoded.indexOf(":");
    // First colon only: "user:pa:ss" is a password containing a colon.
    if (colon === -1) return null;
    return {
      scheme: "basic",
      user: decoded.slice(0, colon),
      password: decoded.slice(colon + 1),
    };
  }

  return { scheme: "other", name, parameters };
}

