import { createHash } from "node:crypto";

export function strongEtag(body: Buffer): string {
  // A hash of the bytes changes exactly when the representation does.
  return `"${createHash("sha1").update(body).digest("base64url")}"`;
}

export function weakEtag(version: number, size: number): string {
  // Derivable from metadata, and honest about being weak.
  return `W/"${version}-${size}"`;
}

export function parseEtagList(header: string | undefined): string[] {
  if (typeof header !== "string") return [];
  return header
    .split(",")
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0);
}

export function etagMatches(
  candidate: string,
  current: string,
  options: { strong: boolean },
): boolean {
  if (candidate === "*") return true;

  const weakCandidate = candidate.startsWith("W/");
  const weakCurrent = current.startsWith("W/");

  // Strong comparison: a weak tag on EITHER side disqualifies.
  if (options.strong && (weakCandidate || weakCurrent)) return false;

  const opaque = (value: string): string =>
    value.startsWith("W/") ? value.slice(2) : value;

  // No leniency about quoting: an unquoted tag is a client bug, and hiding it
  // produces a client that only works here.
  return opaque(candidate) === opaque(current);
}

