import { createHash } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";

export interface Document {
  body: Buffer;
  contentType: string;
  version: number;
  lastModified: number;
}

const CACHE_CONTROL = "private, max-age=60";
const VARY = "accept-encoding";

function matchesAny(header: string, etag: string): boolean {
  return header
    .split(",")
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0)
    .some((candidate) => {
      if (candidate === "*") return true;
      const opaque = (v: string) => (v.startsWith("W/") ? v.slice(2) : v);
      // Weak comparison: this is a conditional GET.
      return opaque(candidate) === opaque(etag);
    });
