export function createHandler(
  load: () => Document,
): (req: IncomingMessage, res: ServerResponse) => void {
  return (req, res) => {
    const method = (req.method ?? "GET").toUpperCase();
    if (method !== "GET" && method !== "HEAD") {
      const body = Buffer.from(
        JSON.stringify({ error: "method_not_allowed" }),
        "utf8",
      );
      res.writeHead(405, {
        allow: "GET, HEAD",
        "content-type": "application/json; charset=utf-8",
        "content-length": body.length,
      });
      res.end(body);
      return;
    }

    const doc = load();
    const etag = `"${createHash("sha1").update(doc.body).digest("base64url")}"`;
    // One-second resolution, both sides, or the document looks permanently
    // newer than the client's copy.
    const modifiedSeconds = Math.floor(doc.lastModified / 1000);
    const lastModified = new Date(modifiedSeconds * 1000).toUTCString();

    const ifNoneMatch = req.headers["if-none-match"];
    const ifModifiedSince = req.headers["if-modified-since"];

    let notModified = false;
    if (typeof ifNoneMatch === "string") {
      // The entity tag is authoritative; the date is not consulted at all.
      notModified = matchesAny(ifNoneMatch, etag);
    } else if (typeof ifModifiedSince === "string") {
      const since = Date.parse(ifModifiedSince);
      notModified =
        !Number.isNaN(since) && modifiedSeconds <= Math.floor(since / 1000);
    }

    if (notModified) {
      // Validators and caching metadata only: no body, and nothing describing
      // one.
      res.writeHead(304, {
        etag,
        "cache-control": CACHE_CONTROL,
        vary: VARY,
        "last-modified": lastModified,
      });
      res.end();
      return;
    }

    res.writeHead(200, {
      "content-type": doc.contentType,
      "content-length": doc.body.length,
      "cache-control": CACHE_CONTROL,
      vary: VARY,
      etag,
      "last-modified": lastModified,
    });
    res.end(method === "HEAD" ? undefined : doc.body);
  };
}

