export type Directives = Record<string, string | true>;

export function parseCacheControl(value: unknown): Directives {
  const out: Directives = {};
  if (typeof value !== "string") return out;

  for (const part of value.split(",")) {
    const token = part.trim();
    if (token === "") continue;
    const eq = token.indexOf("=");
    const name = (eq === -1 ? token : token.slice(0, eq)).trim().toLowerCase();
    if (name === "" || Object.hasOwn(out, name)) continue; // first wins
    if (eq === -1) {
      out[name] = true;
      continue;
    }
    out[name] = token
      .slice(eq + 1)
      .trim()
      .replace(/^"(.*)"$/, "$1");
  }
  return out;
}

export interface BuildOptions {
  public?: boolean;
  private?: boolean;
  noStore?: boolean;
  noCache?: boolean;
  maxAge?: number;
  sMaxAge?: number;
  mustRevalidate?: boolean;
  immutable?: boolean;
  staleWhileRevalidate?: number;
  staleIfError?: number;
}

export function buildCacheControl(options: BuildOptions): string {
  if (options.public === true && options.private === true) {
    // No defensible interpretation, and real caches disagree - so refuse.
    throw new TypeError("cache-control cannot be both public and private");
  }
  const number = (name: string, value: number | undefined): void => {
    if (value === undefined) return;
    if (!Number.isInteger(value) || value < 0) {
      throw new TypeError(`${name} must be a non-negative integer`);
    }
  };
  number("max-age", options.maxAge);
  number("s-maxage", options.sMaxAge);
  number("stale-while-revalidate", options.staleWhileRevalidate);
  number("stale-if-error", options.staleIfError);

  const parts: string[] = [];
  if (options.public === true) parts.push("public");
  if (options.private === true) parts.push("private");
  if (options.noStore === true) parts.push("no-store");
  if (options.noCache === true) parts.push("no-cache");
  if (options.maxAge !== undefined) parts.push(`max-age=${options.maxAge}`);
  if (options.sMaxAge !== undefined) parts.push(`s-maxage=${options.sMaxAge}`);
  if (options.mustRevalidate === true) parts.push("must-revalidate");
  if (options.immutable === true) parts.push("immutable");
  if (options.staleWhileRevalidate !== undefined) {
    parts.push(`stale-while-revalidate=${options.staleWhileRevalidate}`);
  }
  if (options.staleIfError !== undefined) {
    parts.push(`stale-if-error=${options.staleIfError}`);
  }
  return parts.join(", ");
}

export function freshnessOf(
  parsed: Directives,
  options: { shared: boolean },
): number | null {
  if (parsed["no-store"] === true || parsed["no-cache"] === true) return 0;
  if (options.shared && parsed.private === true) return 0;

  const seconds = (name: string): number | null => {
    const raw = parsed[name];
    if (typeof raw !== "string") return null;
    const value = Number(raw);
    return Number.isInteger(value) && value >= 0 ? value : null;
  };

  if (options.shared) {
    const shared = seconds("s-maxage");
    if (shared !== null) return shared;
  }
  // null, not 0: silence permits a heuristic lifetime, which is a different
  // and much longer thing than "stale immediately".
  return seconds("max-age");
}

