  if (typeof header !== "string") return [];
  const names = header
    .split(",")
    .map((name) => name.trim().toLowerCase())
    .filter((name) => name.length > 0);
  if (names.includes("*")) return ["*"];
  return [...new Set(names)].sort();
}

function collapse(value: string): string {
  return value.trim().replace(/\s+/g, " ");
}

function normalizeAcceptEncoding(value: string): string {
  // Browsers spell the same capability a dozen ways; each spelling would
  // otherwise be a separate stored variant.
  return value
    .split(",")
    .map((token) => token.split(";")[0].trim().toLowerCase())
    .filter((token) => token.length > 0)
    .sort()
    .join(",");
