export function cacheKey(
  request: CacheableRequest,
  varyHeader: string | undefined,
): string | null {
  const method = (request.method ?? "GET").toUpperCase();
  if (method !== "GET" && method !== "HEAD") return null;

  const vary = normalizeVary(varyHeader);
  if (vary[0] === "*") return null;

  const url = new URL(request.url, "http://cache.invalid");
  // Sorting the query is a claim that ?a=1&b=2 and ?b=2&a=1 are one resource.
  url.searchParams.sort();

  const lines = [`${method} ${url.pathname}${url.search}`];
  for (const name of vary) {
    const raw = request.headers[name];
    const value = Array.isArray(raw) ? raw.join(", ") : raw;
    if (value === undefined) {
      // Absent and empty must not share an entry.
      lines.push(`${name}: ${ABSENT}`);
      continue;
