export interface PreconditionRequest {
  method: string;
  headers: Record<string, string | undefined>;
}

export interface Resource {
  exists: boolean;
  etag?: string;
  lastModified?: number;
}

export type Verdict =
  | { kind: "proceed" }
  | { kind: "status"; status: 304 | 412 | 428 };

const UNSAFE = new Set(["PUT", "PATCH", "DELETE"]);

function list(header: string | undefined): string[] {
  if (typeof header !== "string") return [];
  return header
    .split(",")
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0);
}

function matches(candidate: string, etag: string | undefined, strong: boolean, exists: boolean): boolean {
  if (candidate === "*") return exists;
  if (etag === undefined) return false;
  const weakCandidate = candidate.startsWith("W/");
  const weakEtag = etag.startsWith("W/");
  if (strong && (weakCandidate || weakEtag)) return false;
  const opaque = (v: string) => (v.startsWith("W/") ? v.slice(2) : v);
  return opaque(candidate) === opaque(etag);
}

function headerSeconds(header: string | undefined): number | null {
  if (typeof header !== "string") return null;
  const parsed = Date.parse(header);
  // A date we cannot parse must be ignored, not rejected.
  return Number.isNaN(parsed) ? null : Math.floor(parsed / 1000);
}

export function evaluatePreconditions(
  request: PreconditionRequest,
  resource: Resource,
  options: { requireIfMatch?: boolean } = {},
): Verdict {
  const method = (request.method ?? "GET").toUpperCase();
  const safe = method === "GET" || method === "HEAD";
  const h = request.headers;

  if (
    options.requireIfMatch === true &&
    UNSAFE.has(method) &&
    h["if-match"] === undefined
  ) {
    // Refusing the unconditional write makes lost updates impossible rather
    // than merely preventable.
    return { kind: "status", status: 428 };
  }

  const modified =
    resource.lastModified === undefined
      ? null
      : Math.floor(resource.lastModified / 1000);

  // Step 1 / 2: protect the RESOURCE. The date form is a fallback for the tag
  // form, never an additional condition.
  if (h["if-match"] !== undefined) {
    const ok = list(h["if-match"]).some((candidate) =>
      matches(candidate, resource.etag, true, resource.exists),
    );
    if (!ok) return { kind: "status", status: 412 };
  } else {
    const since = headerSeconds(h["if-unmodified-since"]);
    if (since !== null && modified !== null && modified > since) {
      return { kind: "status", status: 412 };
    }
  }

  // Step 3 / 4: protect the CLIENT'S BANDWIDTH.
  if (h["if-none-match"] !== undefined) {
    const hit = list(h["if-none-match"]).some((candidate) =>
      matches(candidate, resource.etag, false, resource.exists),
    );
    if (hit) return { kind: "status", status: safe ? 304 : 412 };
  } else if (safe) {
    const since = headerSeconds(h["if-modified-since"]);
    if (since !== null && modified !== null && modified <= since) {
      return { kind: "status", status: 304 };
    }
  }

  return { kind: "proceed" };
}

