// v3nb05_caching_etags / ex6 - reference solution (author only).
export interface CacheOptions {
  now: () => number;
  ttlMs: number;
  staleMs: number;
  maxEntries: number;
}

export interface CacheStats {
  hits: number;
  misses: number;
  stale: number;
  servedStale: number;
  loads: number;
}

interface Entry<V> {
  value: V;
  storedAt: number;
}

export function createCache<V>(options: CacheOptions): {
  get: (key: string, load: () => Promise<V>) => Promise<V>;
  invalidate: (key: string) => boolean;
  size: () => number;
  stats: CacheStats;
} {
  const entries = new Map<string, Entry<V>>();
  // The IN-FLIGHT PROMISE, not the settled value: this is single-flight.
  const inflight = new Map<string, Promise<V>>();
  const stats: CacheStats = {
    hits: 0,
    misses: 0,
    stale: 0,
    servedStale: 0,
    loads: 0,
  };

  const touch = (key: string, entry: Entry<V>): void => {
    // Map preserves insertion order, so delete-and-set is an LRU bump.
    entries.delete(key);
    entries.set(key, entry);
  };

  const evict = (): void => {
    while (entries.size > options.maxEntries) {
      const oldest = entries.keys().next();
      if (oldest.done === true) return;
      entries.delete(oldest.value);
    }
  };

  const refresh = (key: string, load: () => Promise<V>): Promise<V> => {
    const flight = inflight.get(key);
    if (flight !== undefined) return flight;

    stats.loads += 1;
    const promise = load()
      .then((value) => {
        entries.delete(key);
        entries.set(key, { value, storedAt: options.now() });
        evict();
        return value;
      })
      // finally, not then: a failed load must not poison the key forever.
      .finally(() => {
        inflight.delete(key);
      });

    inflight.set(key, promise);
    return promise;
  };

  return {
    async get(key, load) {
      const entry = entries.get(key);
      const age = entry === undefined ? Infinity : options.now() - entry.storedAt;

      if (entry !== undefined && age < options.ttlMs) {
        stats.hits += 1;
        touch(key, entry);
        return entry.value;
      }

      if (entry !== undefined && age < options.ttlMs + options.staleMs) {
        stats.stale += 1;
        touch(key, entry);
        // The caller already has a value; a failed background refresh is a
        // metric, and an unhandled rejection would end the process.
        void refresh(key, load).catch(() => undefined);
        return entry.value;
      }

      stats.misses += 1;
      try {
        return await refresh(key, load);
      } catch (error) {
        if (entry !== undefined) {
          // stale-if-error: old data beats no data.
          stats.servedStale += 1;
          return entry.value;
        }
        throw error;
      }
    },

    invalidate(key) {
      return entries.delete(key);
    },

    size() {
      return entries.size;
    },

    stats,
  };
}

// v3nb05_caching_etags / ex7 - reference solution (author only).
const MONTHS = [
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

export function formatHttpDate(ms: number): string {
  if (!Number.isFinite(ms)) throw new TypeError(`invalid timestamp: ${ms}`);
  // toUTCString() is IMF-fixdate exactly, fixed-width day field included.
  return new Date(ms).toUTCString();
}

const RFC850 = /^[A-Za-z]+day, (\d{2})-([A-Za-z]{3})-(\d{2}) (\d{2}):(\d{2}):(\d{2}) GMT$/;
const ASCTIME = /^[A-Za-z]{3} ([A-Za-z]{3}) ([ \d]\d) (\d{2}):(\d{2}):(\d{2}) (\d{4})$/;

export function parseHttpDate(value: string | undefined): number | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();

  const rfc850 = RFC850.exec(trimmed);
  if (rfc850 !== null) {
    const [, day, month, year, hh, mm, ss] = rfc850;
    const index = MONTHS.indexOf(month);
    if (index === -1) return null;
    const short = Number(year);
    // The RFC 2822 rule, and the reason this format was deprecated.
    const full = short >= 70 ? 1900 + short : 2000 + short;
    return Date.UTC(full, index, Number(day), Number(hh), Number(mm), Number(ss));
  }

  const asctime = ASCTIME.exec(trimmed);
  if (asctime !== null) {
    const [, month, day, hh, mm, ss, year] = asctime;
    const index = MONTHS.indexOf(month);
    if (index === -1) return null;
    return Date.UTC(
      Number(year), index, Number(day.trim()),
      Number(hh), Number(mm), Number(ss),
    );
  }

  const parsed = Date.parse(trimmed);
  // Ignore what we cannot parse: a bad clock string must not become a 500.
  return Number.isNaN(parsed) ? null : parsed;
}

export function notModifiedSince(
  lastModifiedMs: number,
  header: string | undefined,
): boolean {
  const since = parseHttpDate(header);
  if (since === null) return false;
  // Whole seconds on BOTH sides, or the resource is permanently "newer".
  return Math.floor(lastModifiedMs / 1000) <= Math.floor(since / 1000);
}

