const itemEtag = (id: string, version: number): string => `"${id}-${version}"`;

function strongMatch(candidate: string, current: string): boolean {
  if (candidate === "*") return true;
  // Strong comparison: a weak tag on either side never matches.
  if (candidate.startsWith("W/") || current.startsWith("W/")) return false;
  return candidate === current;
}

export function createVersionedStore(): {
  read: (id: string) => { value: unknown; etag: string; version: number } | null;
  write: (id: string, value: unknown, ifMatch?: string) => WriteResult;
  remove: (id: string, ifMatch?: string) => { status: 204 | 404 | 412 | 428 };
  collectionEtag: () => string;
  size: () => number;
} {
  const items = new Map<string, Item>();

  return {
    read(id) {
      const item = items.get(id);
      if (item === undefined) return null;
      return {
        value: item.value,
        etag: itemEtag(id, item.version),
        version: item.version,
      };
    },

    write(id, value, ifMatch) {
      const existing = items.get(id);

      if (existing === undefined) {
        // Nothing to lose: an unconditional create is fine.
        if (ifMatch !== undefined && ifMatch !== "*") return { status: 412 };
        items.set(id, { value, version: 1 });
        return { status: 201, etag: itemEtag(id, 1) };
      }

      // An unconditional overwrite is a lost update waiting to happen.
      if (ifMatch === undefined) return { status: 428 };
      if (!strongMatch(ifMatch, itemEtag(id, existing.version))) {
        return { status: 412 };
      }

      const version = existing.version + 1;
      items.set(id, { value, version });
      return { status: 200, etag: itemEtag(id, version) };
    },

    remove(id, ifMatch) {
      const existing = items.get(id);
      if (existing === undefined) return { status: 404 };
      if (ifMatch === undefined) return { status: 428 };
      if (!strongMatch(ifMatch, itemEtag(id, existing.version))) {
        return { status: 412 };
      }
      items.delete(id);
      return { status: 204 };
    },

    collectionEtag() {
      // Canonical before hashing: two replicas that received the same writes
      // in different orders must produce the same validator.
      const canonical = [...items.entries()]
        .map(([id, item]) => `${id}:${item.version}`)
        .sort()
        .join("\n");
      return `"${createHash("sha1").update(canonical).digest("base64url")}"`;
    },

    size() {
      return items.size;
    },
  };
}

// v3nb05_caching_etags / challenge - reference solution (author only).
import type { IncomingMessage, ServerResponse } from "node:http";

export interface OriginResponse {
  status: number;
  body: Buffer;
  contentType: string;
  etag: string;
  lastModified: number;
}

export interface Options {
  origin: (
    pathname: string,
    headers: Record<string, string | string[] | undefined>,
  ) => Promise<OriginResponse>;
  now: () => number;
  ttlMs: number;
  staleMs: number;
}

interface Entry {
  pathname: string;
  response: OriginResponse;
  storedAt: number;
}

function normalizeAcceptEncoding(value: string | undefined): string {
  if (typeof value !== "string") return "�";
  return value
    .split(",")
    .map((token) => token.split(";")[0].trim().toLowerCase())
    .filter((token) => token.length > 0)
    .sort()
    .join(",");
}

export function createCachingHandler(
  options: Options,
): (req: IncomingMessage, res: ServerResponse) => void {
  const entries = new Map<string, Entry>();
  const inflight = new Map<string, Promise<OriginResponse>>();

  const load = (
    key: string,
    pathname: string,
    headers: Record<string, string | string[] | undefined>,
  ): Promise<OriginResponse> => {
    const flight = inflight.get(key);
    // One origin call per key, however many callers are waiting.
    if (flight !== undefined) return flight;

    const promise = options
      .origin(pathname, headers)
      .then((response) => {
        entries.set(key, { pathname, response, storedAt: options.now() });
        return response;
      })
      .finally(() => {
        inflight.delete(key);
      });

    inflight.set(key, promise);
    return promise;
  };

  const invalidatePath = (pathname: string): void => {
    for (const [key, entry] of entries) {
      if (entry.pathname === pathname) entries.delete(key);
    }
  };

  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://cache.invalid");
    url.searchParams.sort();
    const method = (req.method ?? "GET").toUpperCase();
    const head = method === "HEAD";
    const key = `${url.pathname}${url.search}\n${normalizeAcceptEncoding(
      req.headers["accept-encoding"] as string | undefined,
    )}`;

    const sendJson = (status: number, value: unknown): void => {
      const body = Buffer.from(JSON.stringify(value), "utf8");
      res.writeHead(status, {
        "content-type": "application/json; charset=utf-8",
        "content-length": body.length,
      });
      res.end(body);
    };

    const serve = (
      response: OriginResponse,
      storedAt: number,
      state: string,
    ): void => {
      const age = Math.max(0, Math.floor((options.now() - storedAt) / 1000));
      const cacheControl = [
        "public",
        `max-age=${Math.floor(options.ttlMs / 1000)}`,
        `stale-while-revalidate=${Math.floor(options.staleMs / 1000)}`,
      ].join(", ");

      const ifNoneMatch = req.headers["if-none-match"];
      const matched =
        typeof ifNoneMatch === "string" &&
        ifNoneMatch
          .split(",")
          .map((entry) => entry.trim())
          .some((candidate) => {
            if (candidate === "*") return true;
            const opaque = (v: string) => (v.startsWith("W/") ? v.slice(2) : v);
            return opaque(candidate) === opaque(response.etag);
          });

      if (matched) {
        res.writeHead(304, {
          etag: response.etag,
          "last-modified": new Date(response.lastModified).toUTCString(),
          vary: "accept-encoding",
          "cache-control": cacheControl,
          age: String(age),
          "x-cache": state,
        });
        res.end();
        return;
      }

      res.writeHead(response.status, {
        "content-type": response.contentType,
        "content-length": response.body.length,
        etag: response.etag,
        "last-modified": new Date(response.lastModified).toUTCString(),
        vary: "accept-encoding",
        "cache-control": cacheControl,
        // Tells the next cache down how much lifetime is already spent.
        age: String(age),
        "x-cache": state,
      });
      res.end(head ? undefined : response.body);
    };

    if (method !== "GET" && head === false && method !== "HEAD") {
      void options
        .origin(url.pathname, req.headers)
        .then((response) => {
          // An unsafe method that succeeded invalidates what was cached here.
          if (response.status >= 200 && response.status < 300) {
            invalidatePath(url.pathname);
          }
          res.writeHead(response.status, {
            "content-type": response.contentType,
            "content-length": response.body.length,
          });
          res.end(response.body);
        })
        .catch(() => sendJson(502, { error: "origin_failed" }));
      return;
    }

    const entry = entries.get(key);
    const age = entry === undefined ? Infinity : options.now() - entry.storedAt;

    if (entry !== undefined && age < options.ttlMs) {
      serve(entry.response, entry.storedAt, "HIT");
      return;
    }

    if (entry !== undefined && age < options.ttlMs + options.staleMs) {
      serve(entry.response, entry.storedAt, "STALE");
      // The request has already answered; a rejection here must not end the
      // process.
      void load(key, url.pathname, req.headers).catch(() => undefined);
      return;
    }

    void load(key, url.pathname, req.headers)
      .then((response) => serve(response, options.now(), "MISS"))
      .catch(() => {
        if (entry !== undefined) {
          serve(entry.response, entry.storedAt, "STALE-ERROR");
          return;
        }
        sendJson(502, { error: "origin_failed" });
      });
  };
}

