references.solution.ts:
// v3nb05_caching_etags / review1 - reference solution (author only).
export interface Req {
  method: string;
  headers: Record<string, string | undefined>;
}

export interface Res {
  status: number;
  headers: Record<string, string | undefined>;
}

const CACHEABLE_BY_DEFAULT = new Set([
  200, 203, 204, 300, 301, 308, 404, 405, 410, 414, 501,
]);

function directives(value: string | undefined): Set<string> {
  const out = new Set<string>();
  if (typeof value !== "string") return out;
  for (const part of value.split(",")) {
    const token = part.trim().toLowerCase();
    if (token === "") continue;
    out.add(token.split("=")[0].trim());
  }
  return out;
}

function hasExplicitFreshness(headers: Record<string, string | undefined>): boolean {
  const cc = directives(headers["cache-control"]);
  return cc.has("max-age") || cc.has("s-maxage") || headers.expires !== undefined;
}

export function isStorableBySharedCache(
  request: Req,
  response: Res,
): { storable: true } | { storable: false; reason: string } {
  const method = (request.method ?? "GET").toUpperCase();
  if (method !== "GET" && method !== "HEAD") {
    return { storable: false, reason: "method" };
  }

  const requestCC = directives(request.headers["cache-control"]);
  if (requestCC.has("no-store")) {
    return { storable: false, reason: "request_no_store" };
  }

  const responseCC = directives(response.headers["cache-control"]);
  if (responseCC.has("no-store")) {
    return { storable: false, reason: "response_no_store" };
  }
  if (responseCC.has("private")) {
    return { storable: false, reason: "private" };
  }

  if ((response.headers.vary ?? "").split(",").some((n) => n.trim() === "*")) {
    return { storable: false, reason: "vary_star" };
  }

  if (request.headers.authorization !== undefined) {
    // Presumed to be about that user unless the author says otherwise.
    const allowed =
      responseCC.has("public") ||
      responseCC.has("s-maxage") ||
      responseCC.has("must-revalidate");
    if (!allowed) return { storable: false, reason: "authorization" };
  }

  const explicit = hasExplicitFreshness(response.headers);
  if (!CACHEABLE_BY_DEFAULT.has(response.status) && !explicit) {
    return { storable: false, reason: "status" };
  }

  const validator =
    response.headers.etag !== undefined ||
    response.headers["last-modified"] !== undefined;
  if (!explicit && !validator) {
    return { storable: false, reason: "no_freshness" };
  }

  return { storable: true };
}
